// ---- Update log: each player sees the updates they missed since their last login ----
const UPDATES = [
  { id: 20, title: 'Laser swords and shields', items: ['Laser swords with custom colors and hilts, previewed in the shop', 'Melee only fires with a melee weapon equipped; the offhand blue shield blocks', 'Saber mod station on your ship'] },
  { id: 21, title: 'Sound, music and B.U.R.P.', items: ['Calm beep-boop music (Menu → Settings to switch it off)', 'B.U.R.P. has a robot voice now', 'Softer footsteps and sound effects on nearly everything'] },
  { id: 22, title: 'Space police bounties', items: ['Marshal Rook posts random bounties across the galaxy', 'Rank up your bounty-hunter skill for gear and big payouts paid into your bank', 'No more raiders jumping you in space unless you shoot first'] },
  { id: 23, title: 'Safer and fairer', items: ['Safe fishing spots', 'Mezar spawns you inside the walls', 'Bank part of your credits', 'No more shooting (or getting shot) through walls', 'Betting has its own pit with a clear scoreboard'] },
  { id: 24, title: 'The Moon and notebook weapons', items: ['Earth\'s Moon is open: low gravity, craters and a dome city', 'Sword-gun, nunchucks, claws, scythe, driller, twin master swords, crossbow and more', 'New pets and helmets'] },
  { id: 25, title: 'Gun mods and ordnance', items: ['Paint your guns and swap rounds (laser to void)', 'Unlock grenades: press Z to throw', 'Gun bench on your ship · L launches your ship'] },
  { id: 26, title: 'Ocean World and prettier space', items: ['Swim underwater and walk into the domes', 'Landing on planets no longer locks you in', 'Nebula, glowing atmospheres and dust streaks in space'] },
  { id: 27, title: 'Velocity, the racing planet', items: ['Every car looks different now', 'Free drive through the canyons and badlands (X, or Garage Gus)', 'Big airtime pays credits'] },
  { id: 28, title: 'Canyon sprints', items: ['Races are point-to-point sprints from the pits across the planet (770–910 m)', 'Canyon walls line every course, with gates every 80 m and six jumps', 'The Velocity map is much bigger', 'Space: smaller, dimmer stars and planets spread further apart', 'This update log, so you never miss anything'] },
  { id: 29, title: 'New armor styles', items: ['9 new armor sets, each with its own silhouette: Gladiator Kit, Deep Diver Suit, Lunar EVA, Shadow Wraps, Robo Chassis, Seer Robes, Tank Suit, Mech Frame and Drome Warplate', 'The old sets got real makeovers too (Recon ghillie, Heavy Plate pauldrons, Hive carapace, Frost fur coat and more)', 'Buy new sets in the Wardrobe once you reach their level; tap any set to try it on first', 'Phone flight controls: just the stick, FIRE and a new BOOST button (the on-foot buttons hide while flying)'] },
  { id: 30, title: 'Fort Ironrock and war vehicles', items: ['New world: Fort Ironrock, the asteroid army base (between Earth and Mezar)', 'Drive a Battle Car (ram spikes + twin MGs), a Battle Tank (cannon) or a Battle Mech (missile salvos + jump jets): press V or Menu → Vehicle on any open planet', 'Quartermaster Brix sells vehicles; Dr. Volta researches armor, weapons and engines', '4 new quests ending with Warlord Krag; finish the first one for a free Battle Car', 'The arena betting scoreboard no longer follows you off the arena planet']},
  { id: 31, title: 'Chapter 6: Earth Sky', items: ['New world above Earth: floating islands joined by sky bridges', 'The Sky Air Base, the Floating City (droids), the Deep Sky Forest, a rebel camp and Drome\'s Sky Fortress', 'Fight Drome, Lord of the Setting Sun, for the Sunslayer Cape', 'Fall off an island and the Air Base fishes you out (it stings)']},
  { id: 32, title: 'Zarlich and Vector are open', items: ['Chapter 7, Zarlich: violet storm world with Flaglem-ti, wild Noptiles, T-rexes, Gosa-lem, Devil Light Rays and flying Tube Sharks; boss: the Storm Mother', 'Chapter 8, Vector: the dark world with shades, the Field of Eyes and the true final boss, the Watcher in the Maw (Cape of the Rising Sun)', 'New pets: Tube Shark and Flaglem-ti (Zix on Zarlich)']},
  { id: 33, title: "Earth: Forest of Life and the Super Swift Arena", items: ['Two new signposts in Earth town lead to them', 'Forest of Life (Lv 8–14): the Tree of Life heals you; Snapvines, Spriggans, Glowmoths and the Rot King; reward: the Thornblade', 'Super Swift Arena: an 11-boss rush, every boss scaled to your level; clear them all for the Swift Champion Cape']},
  { id: 34, title: 'All 20 floors of the Zeltac Ship', items: ['Take the elevator in the plaza (back right corner)', 'Market decks (shops, an arms dealer), Residential rings, Hydroponics bays (fish buyer), Neon Arcades (slot machines)', 'Hostile Engine decks and Alien Quarters get harder the higher you go', "Floor 20 is the Captain's Bridge"]},
  { id: 35, title: 'Character creator', items: ['New Face tab in the Wardrobe: skin (including alien colors), eyes, mouth, hair and hair color', '19,200 possible faces, inspired by the head-design sheet; hit Random for a surprise', 'Choose "No helmet" to show your face; other players see it too']},
  { id: 36, title: 'Welcome to New Jamestown', items: ["Earth's safe zone is now New Jamestown, a walled capital city twice the size", 'Main Street, a fountain plaza, Town Hall, bank, clinic, gun shop, store, pet shop, fish market, diner, hotel and tailor', 'New citizens: Mayor Holloway (town news), Ada the Tailor (wardrobe), Cookie, Auntie Paws, Gil, Scoop the newsie, Banjo Bob, Officer Dent, Hotel Hank, plus a crowd on the streets', 'Signposts to the Forest of Life and Super Swift Arena are by the city gate; the dropship pad is in the north-east']},
  { id: 37, title: 'World raids and Commander mode', items: ["Every 15 minutes Drome's remnants raid a different planet for 5 minutes; a bar at the bottom of the screen shows where (tap it to fly there)", 'Raiders come in waves at the edge of town, scaled to your level, with a raid boss at wave 6; every raider drops Raid Tokens', 'Spend tokens with the Mayor or at Fort Ironrock (Raid Cape, Commander Banner, materials, credits)', 'Commander mode is back as the War Table: an overhead view where you spend command points to drop squads and bosses on the troopers playing that planet']},
  { id: 38, title: 'The Starlight Lounge, 9 unique floors and a world detail pass', items: ['The Zeltac Ship now has 9 floors that each look different (it was 20 with repeats)', 'Floor 5: the Starlight Lounge, a bar with a stage, booths and a disco ball', 'Six regulars to romance: Nyra Voss (ace pilot), Grix (rock poet), Juno Sparks (mechanic), Rhett Calloway (smuggler), Vesper (from Vector) and PIP-9 (a robot studying love). Chat, flirt, give gifts, go on dates', 'Go from Stranger to Partner: partners give a perk, visit your ship and send you messages', 'Every outdoor world got ground detail (flowers, mushrooms, cacti, scrap, crystals, spikes and more), floating particles in the air and birds on green worlds', 'Fishing docks can be stood on; enemies no longer push you out of safe rings']},
  { id: 39, title: 'Ship customizer and scavenging', items: ['Mod your ship: 10 paints, 7 accent colors, plus wings, engines, noses, fins and extras (missile pods, armor plating, trophy spikes and more)', 'Parts change your speed, hull and laser damage; other players see your ship', 'Some parts start unlocked; the rest are scavenged from glowing salvage drifting in space (fly through it) or salvage crates hidden on planets (walk over them)', 'Use the Ship customizer on your bridge or ask Brakka on the Zeltac Ship', 'The "Leave the helm" / "Land" prompt no longer covers your ship']},
  { id: 40, title: 'New galaxy map', items: ['The galaxy map is now a top-down chart of every world, the asteroid belt and the sun', 'Tap a world to see its level range, then autopilot there or fly there yourself', 'Shows where you are, which worlds are locked and where a raid is happening']},
  { id: 41, title: 'Cities come alive', items: ['Every hub got a life pass: market stalls, carts, crates, lamps, benches, signs, string lights and themed props (honey pots in Bug City, holo-ads and vending machines in Robot City, boats and nets in Port Kelp, rovers on the Moon, tents and jeeps at Fort Ironrock, and more)', 'Crowds of locals now wander between spots in every city and stop to hang out', 'Towns glow at night with a warm city light']},
  { id: 42, title: 'Ship decorating (building retired)', items: ['Base building on planets is gone; instead, decorate your ship\'s rooms (Menu → Decorate, or G)', '50 pieces of furniture across Living, Bedroom, Kitchen, Fun, Decor, Tech and Build: sofas, beds, aquariums, arcade cabinets, pool table, jukebox, fireplace, trooper statue, weapon rack, saber display, holo-map table and more', 'Lots are free; the rest you buy once with credits and place as many as you like', 'Some furniture does things: nap in a bed, watch the news on the holo-TV, change music on the jukebox, open the galaxy map on the holo-table, grab a coffee']},
  { id: 43, title: 'The War Table has a purpose', items: ['Support mode: call in airstrikes, sentry turrets, supply drops, allied trooper squads and an orbital lance on any open planet', 'Great during raids: points recharge faster, and your support kills earn Raid Tokens', 'Invade mode is still there for dropping enemy squads on other players']},
  { id: 44, title: 'The Residential Ring', items: ['Zeltac floor 3 is now a real neighborhood: 12 apartments around a park with a fountain, playground, community garden, mailbox and kids running around', 'The six Starlight Lounge regulars live here; once you are friends, knock and visit their themed apartment (Nyra has ship models, Grix a rock garden, Juno a workshop, and so on)', '"Spend the evening" at their place to grow closer', 'Dating someone? Invite them to live on your ship: they move into your quarters and leave you gifts']},
  { id: 45, title: 'Graphics styles', items: ['Menu → Settings → Graphics: Classic PS1, PS1 Glow (new default), Crisp Toon, Neon Night or Golden Hour', 'Adds glow on lights and neon, richer color and optional scanlines']},
  { id: 46, title: 'New Jamestown, twice as big', items: ['The capital is now a 90-meter walled city with wide boulevards, sidewalks, a big fountain plaza, a columned Town Hall, 21 buildings (arcade, cinema, garage, apartments) and a park with a pond and gazebo', 'Earth\'s wilds were pushed outward to make room, so the whole planet is bigger too', 'More citizens, more street life, parked hover cars']},
  { id: 47, title: 'Fixes: racing, bank, clutter', items: ['Racing works now: talking to Race Marshal Vroom always gets you to the Race menu (accepting his quest used to just close the conversation)', 'Races are simpler time trials: no walls, no AI traffic, big gates, a light beam over the next gate, and gold/silver/bronze times', 'The bank has a clean Deposit / Withdraw layout', 'Ground clutter and city props no longer spawn inside buildings and structures', 'Quest-giving shopkeepers reopen their shop menu after you accept or decline']},
  { id: 48, title: 'Render styles', items: ['Menu → Settings → Render style: Retro PS1, HD Stylized or Semi-Realistic (the game reloads to switch)', 'HD styles render at full resolution with smooth textures, real-time sun shadows, bloom on lights and film-style color', 'Semi-Realistic uses physically based materials with surface relief; HD Stylized uses cel-shaded toon lighting']},
  { id: 49, title: 'Combat feel, Codex and New Game+', items: ['Hits now show damage numbers (orange for big hits), guns have muzzle flashes, kills flash, bosses go down in a pillar of light, and explosions shake the screen', 'Level-ups fire a golden beam', 'Menu → Codex: 36 achievements with credit rewards, 3 daily challenges (the same for everyone each day), a Bestiary of every creature you have beaten, and your lifetime stats', 'Finish the Zeltac storyline to roll the ending credits and unlock Ascension (New Game+): tougher enemies, more XP and an Ascendant cape', 'New settings: look speed, invert look, field of view, screen shake and damage numbers']},
  { id: 50, title: 'Lore, controls and photo mode', items: ['Codex → Lore: an entry for all 17 worlds plus the factions and figures behind the war, unlocked as you explore', 'The first time you land on a new world you get a big title card', 'Press F1 (or Menu → Controls) for the full controls list; the title screen key list is up to date too', 'Photo mode: press P (or Menu → Photo mode) to hide the HUD and gun; K saves a picture', 'New hotkeys: C opens the Codex, M opens the galaxy map on your ship', 'One-time tips help new troopers find medkits, the ship, vehicles, decorating and raids', 'Codex → Leaderboards: see how you rank against every trooper for level, kills, bosses, Super Swift rounds, raids, achievements, fish and each race track', 'Fixed long lists in menus squashing their rows together']},
  { id: 51, title: 'Boarding, drones, Chapter 5 and a new HUD', items: ['Brand-new HUD: glass panels, a compass tape with your objective marker, a round radar, segmented health, and a menu that opens as a grid of tiles', 'Phones: tidy right-hand column for Reload, Swap, Grenade and a new HEAL button (shows your medkit count). Tap your ammo to reload. Desktop: click the medkit chip or press H', 'Board ships in space! Freighters, raider corsairs, Drome cutters and hive ships drift between worlds. Fly close, dock, clear the crew and loot the hold for credits, ship parts and drone parts', 'Combat drone: buy one at the drone bay on your ship (or Fort Ironrock / Brakka). Upgrade its twin blasters, micro-missiles and repair beam, and pick a paint', 'Chapter 5 · The Dark Fleet: chase Drome\'s fleet from Robot City, board the flagship Eclipse, face Admiral Sable, then retake Fort Ironrock. The whole story now runs in order, Chapter 1 to 8', 'Epilogue: after the Watcher falls, Captain Vega has one last thing for you', 'Codex → Ending replays the ending, now a real cutscene with fast-forward and skip', 'Players online: see who is on which world and Join them (Menu → Players, or from the Leaderboards)', 'Change your callsign any time in Settings', 'Fixes: the leaderboard picker no longer shows up in other menus, race gates now face the road, Ada the Tailor no longer hands out Robot City quests on Earth, and the two Fenns stopped sharing quests']},
  { id: 52, title: 'HUD fixes', items: ['The new HUD now looks right on every phone: the old blue panels and button positions were showing through on some devices', 'The Grenade button is called Ordnance again', 'Landscape on phones: the quick-action column no longer covers the radar, and the joystick no longer sits on your health panel']},
  { id: 53, title: 'Towns, pads and the armory', items: ['Townsfolk no longer spawn stacked on top of each other and standing still (Moon, Mezar, Capitone, Robot City and Earth Sky were worst). They now spread out and walk around', 'Landing pads that were clipped into buildings or blocking doorways now move to the nearest open ground (the Moon pad is outside the dome now)', 'The armory gun rack is mounted flat against the wall, with six different guns on pegs', 'The weapon panel no longer shows the gun name, just your ordnance charges', 'The Reload button hides when your gun has unlimited ammo']},
  { id: 54, title: 'Wizardry', items: ['The full staff line from the notebooks, Lvl 1 to Lvl 100: Apprentice, Ember, Lightning, Glacier, Plague, Blast, Archmage, Stormcaller, Inferno, Void, and the Staff of the Setting Sun', 'New spell effects: arcane sparks that jump to nearby foes, frost that slows and can freeze enemies solid, and Blast Staff explosions', 'Staffs never need ammo: they recharge their mana between bursts', 'Merla the Wizard has opened a staff shop in New Jamestown (by the fountain). Maxurge on Capitone and Seer Ixa on the Zeltac Ship sell the stronger staffs', "The Wizard's Path: three quests from Merla that end with the Staff of the Setting Sun", 'Wardrobe: Wizard Robes and a Wizard Hat']},
  { id: 55, title: 'ART OF WAR: SETTING SUN 1.0', items: ['Version 1.0 is here. Thank you for flying the Setting Sun!', 'The full story, Chapters 1 to 8 plus the epilogue; 17 worlds; boarding, racing, raids, fishing, pets, drones, romance, staffs and New Game+', 'Final bug sweep: every world, deck, menu and quest checked; townsfolk walk more smoothly and use less of your phone']},
  { id: 56, title: '1.0.1', items: ['Fixed the flickering streets in New Jamestown: the roads, sidewalks, plaza and crosswalks were drawn at the same height and fought each other. Each layer now sits cleanly on top of the last']},
  { id: 57, title: '1.1: A proper ship, and real spells', items: ['Your ship has been refitted: plated deck floors, ribbed hull walls and paneled ceilings, all at the right scale, with a guide stripe down the corridor and framed doorways', 'Every room has its own look and lighting: carpeted wood-paneled quarters, a steel armory, a grated cargo bay, a white-tiled med bay, a marble-and-red trophy hall, a greenhouse garden and a hazard-striped hangar', 'Every room has a job. Quarters: sleep for full health and Well Rested (+15% XP for 15 min), wardrobe, personal log. Armory: gun rack, workbench, ordnance rack that refills your charges. Cargo bay: sell loot from the ship. Med bay: healing pod and an armor stim (take 25% less damage for 10 min). Trophy hall: trophies and the Hall of Records leaderboards. Garden: grows medkits, plus a fish tank. Hangar: vehicle bay, your bike, and a launch pad', 'The bridge has a console row and a proper captain\'s chair', 'Staffs and wands now cast named spells (Fireball, Chain Lightning, Ice Shard, Plague Cloud, Blast Wave, Void Rift, Sunburst and more) from a mana bar that refills on its own. No rounds and no reloading', 'Active buffs (Well Rested, Armor Stim) show on the HUD']},
  { id: 58, title: '1.2: The soundtrack', items: ['Real music! New Jamestown has its own theme, Velocity races to an overture, Fort Ironrock rides a tidal wave, and the rest of the galaxy has its own groove', 'Fights switch to battle music, and bosses get their own apocalyptic theme. Music crossfades cleanly between places and moments', 'Your ship alternates between two calm songs. Your love interest has a song too: it fades in when they are close or when you talk', 'The Starlight Lounge is a full party now: light-up dance floor, DJ Nova on the decks, lasers, strobes, a dancing crowd and a four-song playlist. The President of the New United States is there. He is having a great time', 'The first time you board your ship you get a short film of it (skippable after a few seconds)', 'Settings: Music can be Soundtrack, Ambient, Beep boop or Off, plus a music volume slider', 'Menu is now a pull-up drawer: swipe up or tap the MENU tab at the bottom (Tab on keyboard). Buttons are light and see-through']},
  { id: 59, title: 'The Prologue', items: ['The first-time-aboard film is now a Prologue: a tour of the whole galaxy (Earth, Mezar, Capitone, Robot City, the Zeltac Ship), the rise of Drome and his fleet, the eye opening in the dark, and your ship launching from Earth', 'Narrated with subtitles for now (voice coming soon). Replay it any time from the Codex', 'In the Starlight Lounge the music now comes from the DJ speakers: louder and clearer up front, panned toward the stage, muffled at the back of the room']},
  { id: 60, title: 'Music Drive and Cinema', items: ['Ship music now comes from speakers on the bridge, along the corridor and in each room', 'First time in the Starlight Lounge: a short intro film (skippable after a few seconds)', 'The Prologue only plays the very first time you board your ship', 'Codex → Cinema replays every cutscene you have unlocked: the Prologue, the Starlight Lounge and the Ending']},
  { id: 61, title: 'Dance floor rules and a roomier screen', items: ['In the Starlight Lounge your weapons are put away: you get a DANCE button instead (click on desktop)', "The President's Nebula Dust now puts a burning cigarette in your hand, and for 15 seconds the music gets louder", 'Settings → HUD size: Small, Medium or Large (phones default to Medium). Settings → Quest tracker: Compact hides the extra text', 'Fullscreen: Menu → Fullscreen or Settings → Fullscreen. If your app blocks it, open the game link in your phone browser', 'Fixed music going silent on some phones and in the Claude app: if the speaker effects mute the music, the game switches them off and keeps playing']},
  { id: 62, title: 'Music fixed', items: ['Music plays again everywhere. The Music Drive is parked while we rebuild it', 'Ship walls, floors and ceilings no longer slide around as you walk', 'Residential Ring: the apartments no longer block the elevator']},
  { id: 63, title: 'The Crucible: raids at Fort Ironrock', items: ['Raids now happen at Fort Ironrock. Use Raid Command (the red terminal by the landing pad, or ask General Hale or Sgt. Torque) to deploy into the Crucible, a hardcore raid arena', 'Pick the deadliness yourself, from Recruit to Apocalypse. Enemies get tougher and hit harder, and the payout grows up to 12×', 'Three waves of elite troops, then the Iron Tyrant with a shockwave you must dodge (get far away or jump). Die and the raid is over', 'Everyone in the Crucible on the same setting fights the same Iron Tyrant: your damage adds up together', 'New healing spells: the Mending Staff (Merla) and Lifebloom Staff (Seer Ixa) heal friends you aim at. Lifebloom also heals friends around them and a little of you', 'Fort Ironrock has its own intro film (replay it in Codex → Cinema), and it only ever plays Tidal Wave']},
  { id: 64, title: 'Game editor (owner only)', items: ['Menu → 🛠 Editor (or F9): place crates, barrels, walls, rocks, trees, lamps, lights, neon signs, platforms and enemy spawns right where you stand', 'Rotate, resize, move, teleport to or delete anything you placed', 'Tune any weapon (damage, fire rate, magazine, price, level) and any enemy (health, speed, XP)', 'Edits save automatically and go live for every player. Save & share copies everything as text']},
  { id: 65, title: 'Gun + staff loadout, and dual wield in New Game+', items: ['Carry a gun and a staff at the same time: equip one of each, then press Y (or tap the ammo box) to switch', 'New Game+ (Ascension 1 and up): switching goes Gun → Staff → BOTH. In both mode you fire your gun and cast your spell together, each with its own ammo and mana', 'The ammo box shows your other weapon and its ammo or mana']},
  { id: 66, title: 'Characters, body type and controller', items: ['Every character now has a permanent ID. Making a new character never replaces an old one, even with the same callsign', 'Start screen → 👥 Characters: switch between all your characters. Characters save automatically to browser & cloud', 'Moving to a different device? Characters → Download file or Copy code, then Upload file or Paste code on the other device', 'Pick ♂ Male or ♀ Female on the start screen', 'Controller: tap LB for the bag, hold LB for gun/staff, heal, codex and dance; R3 heals; D-pad works in menus; A skips cutscenes; rumble when you get hit', 'Wardrobe → Armor: switch Male / Female any time', 'Flying into an asteroid now bounces you off instead of trapping you', 'Removed the old Skip tutorial button']},
  { id: 67, title: 'Cleaner screen', items: ['The minimap now stays north-up; your arrow turns instead', 'The compass is smaller and sits under the minimap', 'Boss health moved out of the middle of the screen to the top-right, under the compass', 'Leave the helm (and other flying prompts) moved to a small chip in the bottom-left', 'Wardrobe shows armor, helmets and faces from the front (capes still from the back)']},
  { id: 68, title: '1.8: Gun sounds, your look, and smoother PC controls', items: ['Gunfire works again: sound effects could get stuck silent after pressing Start. Now any key or tap wakes them up, and iPhones play them even on silent mode', 'Every weapon sounds new: punchy blasters, cracking rifles, booming shotguns with a pump, a whooshing rocket launcher, a twanging crossbow, a buzzing Stinger, and its own voice for every spell element. Reloads, empty clicks, shell casings and explosions are new too', 'New default look: PS1 render, Crisp Toon, Sharp pixels. First launch lets you pick a look (with screenshots) and your music. Change both any time in Menu → Settings', 'PC: closing a menu puts you straight back into aiming (no more wasted shot to grab the mouse). One Esc opens the pause menu. Press 1–9 to pick menu options, 1 gun · 2 staff · 3 melee, mouse wheel swaps weapons, I opens the bag', 'New Game+ only unlocks after you finish the story', 'The end credits play the hymn']},
  { id: 69, title: 'Raid notices out of the way', items: ['The raid chip is now small and sits above your health (top-left on phones) instead of the middle of the screen', 'The next-raid countdown only shows in the last minute', 'Raid alerts, waves and boss calls show on that chip and in the chat log instead of a big popup']},
  { id: 70, title: '1.9 · Fixes round one', items: ['Arena: the betting card shows while bets are open, then shrinks to a small chip in the corner once the fight starts', 'Earth: the floating lava pool now sits on the ground, and the river bridge reaches both banks', 'Other players now see the actual gun or melee weapon you are holding, and see you dancing', 'Starlight Lounge: no weapons in your hands', 'Zeltac: you only see players on your own floor', 'Chat still shows when quests are hidden', 'Ship and indoors: the jetpack no longer pushes your head through the roof', 'Ship exhaust comes out the back now, with new colors in the ship shop (Exhaust tab)', 'The President party button only shows when you are right next to him', 'PC: fixed the mouse randomly jumping. After a menu, click once to take back aiming (that click does not shoot)']},,
  { id: 71, title: '2.0 · The menu tablet', items: ['The menu is now a tablet your character holds up. Six big buttons: Ship, Vehicles, Bag, Journal, Social and Settings', 'Ship holds Beam up, Launch, Galaxy map and Decorate. Vehicles holds your vehicle, bike and drone. Unstuck lives in Settings', 'Settings and the pause screen have four tabs (Graphics, Sound, Controls, Game), so nothing scrolls', 'Long shop and sell lists show a page at a time with arrows (arrow keys work too)', 'PC: Tab opens the tablet, number keys pick a button, Esc or Backspace goes back']},
  { id: 72, title: '2.1 · Shared world, bag equip, balance', items: ['Everyone in the same world now sees the same monsters in the same places, with the same health. Hit one together and it dies for everybody, and everyone who hurt it gets the kill and loot', 'The bag lists your guns, staffs and melee weapons with an Equip button', 'Balance: the Backpack Minigun, Storm Rifle and Marshal Repeater hit less hard, levels add less damage, and gun upgrades are +8% per tier']},
  { id: 73, title: '2.2 · Bubble City grows', items: ['Bubble City has three new domes joined by glass tunnels: the Bubble Market (Auntie Nacre buys and sells), the homes dome (Old Barnacle and Pip) and a kelp farm (Farmer Kelpa)', 'A Pearl Fountain and benches in the main dome, fish schools circling the city, a parked sub and buoys', 'Walking out of a dome no longer pops you up to the surface. You start swimming from the sea floor', 'Siege Bots: legs are attached to the body again and stand on the ground']},
  { id: 74, title: '2.3 · The Art of War', items: ['A new opening trailer, The Art of War, set to the Rising Sun song: the battlefield, the general, a lone warrior, the fallen masterpiece and a statue of rubble, then the galaxy and a fleet battle', 'It plays once when you start a new game, and you can replay it any time from Codex, then Cinema', 'The big eye boss, the Watcher in the Maw, now fights to Event Horizon Collapse', 'Cutscenes in the Codex always switch to their own music', 'Cutscenes play their music even when the game music is set to Ambient or Beep boop (Off still keeps them silent)']},
  { id: 75, title: '2.4 · Velocity, the magnet storm planet', items: ['Velocity is now a flat plain of gray glass under a storm that never ends: lightning bolts, rainbow rain and fog that rushes past as you speed up', 'Pit Row floats 20 m above the plain on magnet pylons, with a long ramp bridge down to the start line', 'Hover driving: cars slide on magnets with almost no friction. Hold Space (or DRIFT) to drift, which charges a boost when you let go. Shift boosts', 'C (or CAM) switches between hood, chase and far chase cameras. Your car has headlights', 'Three new courses across the open plain with ring gates: Storm Sprint, Magnet Mile and Thunder Run, on the shared leaderboards', 'Garage Gus sells five levels of Engine, Magnets and Boost, plus stripe colors and patterns', 'Every car is rebuilt with hover pads, lights and paint, and there is a new Hover Bike', 'Other players see you in your car']},
  { id: 76, title: '2.5 · Aim comes right back', items: ['Closing a menu, the bag, a shop or the tablet takes the mouse back for aiming on its own. No cursor on screen and no extra click', 'If the browser blocks it for a moment (right after Esc), the cursor stays hidden and your next click only grabs the mouse, it never fires']},
  { id: 77, title: '2.6 · New backpack', items: ['The bag (I) is now a full inventory screen: equipment on the left, a 60 slot grid in the middle, item details on the right', 'Filter by Weapons, Medical, Materials, Quest, Valuables or Misc, search by name, and sort by type, rarity, weight, value or newest', 'Equip guns, staffs, melee weapons, armor and ordnance from the bag. Drag items onto slots on PC, or tap Move then tap a slot on phones', 'Four quick slots on keys 4 to 7 (buttons on phones) for medkits, weapons and ordnance. They point at your real items, never copies', 'Pickups show a small card with the item. When the bag is full the loot stays on the ground and tells you, instead of vanishing', 'Drop 1, half or a whole stack. Quest items can never be dropped', 'The lava pit in the Maw on Vector now sits down in the crater floor instead of floating above it', 'The Art of War opening trailer is put away for now. New games start with the usual intro']},
  { id: 78, title: '2.7 · Ship storage and room upgrades', items: ['Own a Cargo Bay? Select loot in your bag and Beam it to your ship. Open Ship storage from the bag or the new terminal in the Cargo Bay', 'Ship storage holds 100 slots and doubles with each Cargo Bay level. Level 5 is the Black Hole Box: unlimited storage, and it sits spinning in your Cargo Bay', 'Take items back out aboard your ship. From Cargo Bay level 3 you can beam them down anywhere', 'Every room now upgrades to level 5 at the Engineering terminal: better rest, more ordnance charges, cheaper gun mods, stronger stims, faster gardens, faster vehicles and boss bonus credits', 'Loot now stacks up to 25 per bag slot (medkits 10), so big hauls fill the bag and storage matters. Nothing you already carry is lost']},
  { id: 79, title: '2.8 · The outlaw underworld', items: ['Outlaw rep: crimes raise it, good deeds lower it. Clean, Shady, Outlaw, Wanted, Most Wanted. Your tier shows on the HUD; tap it for your record', 'Every planet has a hidden hatch on the outskirts leading down to the Underworld: Sly Marlo the Fence buys contraband, Madame Vex runs the black market', 'McKlunkies stands on every planet: burgers and fries heal you, and the back counter buys illegal goods once you are Shady', 'Contraband has a red triangle and only Fences buy it. Stores won\'t touch it', 'Scavengers and drifters roam outside the cities. They leave you alone unless you start it', 'Go Wanted and the Marshals put a growing bounty on you and send hunters. Pay Marshal Rook 1.5x the bounty to clear your name, or use Forged Papers', 'Signed-in players share one board: clean players take Marshal bounties on Wanted players, outlaws post and take Hits in the Underworld. You can only fight a player while one of you holds the contract on the other, and they can fight back', 'Raid Merchant Haulers in space for contraband. Wanted pilots get chased by Marshal patrols', 'New Zeltac floors: The Undercroft and the Senate Archive, with a four-part story about the President\'s money'] },,
  { id: 80, title: '2.8.1 · Bubble City fixes', items: ['Auntie Nacre, Old Barnacle, Farmer Kelpa and Pip were standing in open water outside Bubble City. They are back inside their domes', 'Anyone swimming outside the domes, other players included, now wears a glass dive dome over their head'] },
  { id: 81, title: '2.9 · Substances and the Lab', items: ['New optional system, off until you switch it on in Settings → Game → Substances', 'Legal boosts at every general store: Focus Fizz (+15% XP), Stim Patch (+15% speed), Iron Gum (take 10% less damage)', 'Illegal ones with a red triangle: Void Spice, Neon Dust, Glimmer and Red Haze from Madame Vex or the McKlunkies back counter. Bigger boosts, wild colors, and a chance of a bad trip with shadow figures and whispers', 'Build a Lab on your ship to brew them from materials. It is the only place to cook Blackout. Owning one keeps you Wanted until you tear it down at the Lab console', 'Take one from the bag, the ✦ chip on the HUD, the new USE button on phones, or press U'] },
  { id: 82, title: '2.9.1 · Decorate, pop-ups and the President', items: ['Decorate now lives in the Ship menu. It is greyed out until you are inside your ship', 'New compact build bar at the top of the screen, and the HUD gets out of the way while you decorate', 'The piece you are placing shows as a see-through copy with a yellow arrow out of its front, and turns in all four directions', 'Pop-up messages are now a small see-through pill near the bottom, and area names are smaller', 'President Starling wears a real gold power suit now instead of a box'] },
  { id: 83, title: '2.10 · Editor place mode', items: ['Editor → Place → Place mode: a see-through preview sits wherever you aim, with a yellow arrow for its front. Fire or Place drops it, and you can keep placing', 'Grid on snaps to half metres and 45° turns; Grid off places freely in 15° turns. Arrow keys nudge (Shift for bigger steps), Q/E turn, PgUp/PgDn raise and lower. Phones get a nudge pad', 'Aim at something you placed to Move, Copy or Delete it. Undo takes back the last 20 changes', 'New hanging lamp, chain light, hanging plant and banner. They hang from the ceiling, or get a post outdoors. Ship Decorate has them under Decor', 'Aim at any NPC to move them, turn them, or rewrite what they say', 'New Shops tab: what stores pay for loot and which guns each gunsmith sells. The Enemies tab now sets each spawn group’s levels and count, and can move a spawn area to where you stand'] },
  { id: 84, title: '2.11 · The fishing update', items: ['You now hold your rod while you fish, and other players see it in your hands. Basic, Hive and Frost rods each have their own look', 'New Abyss Rod from Old Marlin on Ocean World (6,000 cr): the biggest catch window and the best odds of rare fish', 'A real cast: swing the rod and the bobber arcs out onto the water. It bobs while you wait, dips with a splash on a bite, and gets pulled in as you reel', 'The fishing box is now a small panel so you can watch the water. Click or tap the screen to reel', 'Every catch swings up in front of you with its name, size and rarity (Common, Uncommon, Rare or Legendary). Your biggest of each species is saved, so watch for New record!'] },
  { id: 85, title: '2.11.1 · Playtest fixes', items: ['Menu rows on phones no longer squeeze names into one word per line (ship upgrades, bounty board and others)', 'Gunsmith and wardrobe previews sit in the corner on phones, so the list and Done button fit without scrolling', 'The New World Discovered card is smaller, see-through, and waits until intro scenes finish', 'Signs and holo ads no longer read backwards when you see them from behind'] },
  { id: 86, title: '2.11.2 · Ocean World quests are back', items: ['The President storyline had accidentally replaced four Ocean World quests (Salt and Subs, Jelly Jam, Pearls for the Mayor, The Sword Master), which also blocked The Deep. They are back, and the President storyline keeps going separately', 'The quest arrow now points you to the Zeltac elevator for the Undercroft and the Senate Archive, and to The Mole once you are on his floor'] },
  { id: 87, title: '2.12 · Story pacing, fishing fights and a livelier ship', items: ['Story pacing: you no longer end up thirty levels above the next chapter. Big quest rewards and boss kills are tuned to their own level, and enemies give less XP once you clearly out-level them.', 'Fort Ironrock\'s war zones, Earth Sky, Zarlich and Vector now match where they sit in the story. Fort\'s training range is still a beginner area, and the war there starts after the Dark Fleet.', 'The President storyline now opens after Robot City.', 'Fishing: a new line-tension fight. Hold to reel, ease off when the line goes red, and watch for big fish making a run. Better rods take more strain and reel faster.', 'Your ship\'s hallway has pipes, crates, lockers, a water cooler, a status screen, a viewport onto the stars, and crew walking the deck who stop for a chat.', 'Phones: the message log keeps the newest three lines, fades sooner and is easier to read. On PC it no longer overlaps the raid button.', 'Long lists like the gunsmith and the Codex get filter buttons: Can buy, Owned, Locked (or Done and To do).'] },
  { id: 88, title: '2.12.1 · A livelier Underworld, and skip the scenes', items: ['The Underworld den has a bartender who sells drinks, Lucky Seven\'s dice table (bet credits, beat her roll, win double), booths, a jukebox, arcade cabinets, and Rattle the information broker with rumors and tips.', 'Settings → Story scenes: set it to Skip and every first-time intro skips itself. Replays from the Codex cinema still play.'] },
  { id: 89, title: '2.12.2 · First-minute fixes', items: ['Phones: the Play button on the Choose Your Look screen was hidden below the bottom edge. It now stays on screen.', 'Enemy and NPC name tags no longer fill the screen when something is right in your face.', 'New players without a ship no longer see raid countdowns for worlds they cannot reach.', 'The galaxy map now says exactly what opens a locked world.'] },
  { id: 90, title: '2.12.3 · Tidier screens', items: ['When you land on a new world, tips and objective pop-ups wait for the world title card instead of landing on top of it.', 'The update log keeps the newest few updates open and folds older ones down to their titles. Tap one to read it.'] },
  { id: 91, title: '2.12.4 · Notebook gallery', items: ['The Start button on the title screen no longer blinks.', 'New checkbox on the start screen: choose whether drugs and drinks are in your game before you begin. You can still change it later in Settings.', 'Codex → Credits → See the drawings: nine of Phil and Caleb\'s high-school notebook drawings, side by side with the characters they became.', 'The ending credits now show some of those drawings too.'] },
  { id: 92, title: '2.13 · The Greater Maw', items: ['New finale: after the Watcher dies, a wormhole tears open near Vector. Only players who beat him can see it. Upgrade your ship first, then fly through.', 'Inside is the Greater Maw, a huge, grosser Watcher floating in a dead star field. You go in alone... until Vega, the Masters and every friend you made show up to help. You can fly back in and fight him again any time.', 'New top ship tier at Zeltac: lasers, hull and engines all get a fourth level.', 'Story fixes: Drome escapes Earth in a shuttle, the Eye in the Dark is set up from the start, Ramick is now a required stop before Robot City, and side quests name the right villain.', 'Vega narrates the trailer.', 'McKlunkies: orders are now taken by a smiling robot face on the wall.', 'Monster levels on later worlds were smoothed so the story never asks you to fight way above your level.', 'iPhone: if something goes wrong the game now shows the error on screen so testers can screenshot it, and it offers a reload if the phone runs out of graphics memory. Phones also render at a lighter resolution in the HD looks.'] },
  { id: 93, title: '2.13.1 · Velocity storm', items: ['Velocity is stormier: heavy fog, a dark sky and a short view distance. The ring gates still glow through it.', 'Rainbow lightning: thick, many-colored bolts strike every few seconds and flash the sky the same color.', 'New default Cockpit camera (C to switch): dashboard, steering wheel that turns with you, your hood in your paint, and rainbow rain on the windshield with wipers.', 'Cars are 12% faster. Gold times were raised to match so medals stay fair.', 'Traffic: hover cars cruise the flats. Hit one and you bounce.', 'Rainbow spray kicks up behind your car.', 'Park and get out: your car now stays where you park it. Walk up and press X or E to get back in, or press X twice from far away to call it.', 'The glassy floor no longer swims and wobbles as you drive (the PS1 jitter is now off for the big flat pieces).'] },
  { id: 94, title: '2.13.2 · Bridges, lakes and alien fish', items: ['Bridges on Earth and Capitone no longer float metres above the ground: they now run bank to bank and slope to meet both sides.', 'The Forest of Life path to the Heartwood now has a footbridge over the river.', "Zarlich's Glowing Lake was dry. It holds water now, and you can fish there.", 'Rivers and pools always sit below the water line on every world.', 'New catch card: when you land a fish you see its type, weight (kg and lb), length and value. Bigger than average fish pay a size bonus on the spot.', 'Ten alien fish that look alien: Lanternjaw, Void Gulper, Three-Eyed Gawker, Tentafish, Shard Ray, Violet Spinefish, Jellopod, Star Jelly, Hive Skimmer and the Gearfish. Find them on Mezar, Capitone, Ocean World, Robot City and Zarlich.'] },
  { id: 95, title: '2.13.3 · Velocity, darker', items: ['Your car now waits right in front of you when you land in Pit Row. Walk up and press E or X to drive.', 'Menu → Vehicle now lets you pick which car to drive. On Velocity it lists your hover cars; elsewhere it lists your war vehicles.', 'Heavier rainbow rain, a rolling storm-cloud ceiling, and a much darker sky. The flash color of each lightning bolt lights up the clouds.', 'Brighter, longer headlights with a beam you can see in the rain.', 'Windshield rain looks like water now: clear beads with a glint and a dark rim, running streaks, and fine mist the wipers clear.', 'Traffic cars no longer drive backwards, and they have headlights.', 'Some shady locals moved into Pit Row.'] },
  { id: 96, title: '2.13.4 · Guns, a gun range and a real B.U.R.P.', items: ['Every gun got a makeover: sights, a light strip in its color, a muzzle brake and a slide that kicks back when you fire.', 'Alien guns now have a floating energy core, spinning rings and glowing vents, and burst a ring of their own color when fired. Regular guns flip out brass casings.', 'Other players now see your gun with its paint, and see it flash and fire.', 'New ship room: the Gun Range (1,200 cr and 6 circuits). It is the one place on the ship you can shoot, with free ammo, pop-up targets and a 30 second drill. Beat your best score for credits.', 'B.U.R.P. has a real robot voice now instead of the browser speech.'] },
  { id: 97, title: '2.13.5 · Cockpits, radio and the Halo Line', items: ["Ship cockpit: press C in space (or the camera button) to fly from the pilot's seat, with a live radar, hull and weapons screens, and a stick and throttle that move", "Ship ammo: 1 Lasers, 2 Plasma, 3 Flak, 4 homing Missiles (6 in the rack, they reload), 5 EMP that freezes raiders around you", "Radio: press R (or the radio button) in your ship or Velocity car to flip through four stations made from the soundtrack", "Bobbleheads: 9 to earn. They ride on your dash and wobble when you turn. N swaps them", "Velocity car cabin rebuilt: a live gauge cluster, a real steering wheel, a center screen with radio and traffic radar, vents, doors, mirror and storm-colored mood lights", "The Halo Line on Velocity: drive into the gates at the east and west edges and ride a magnet tube around the planet, past the glass window onto Prism Deep, the rainbow city of the Hydrans", "Velocity: lighter layered rain, a dark wet road with puddles, cars that hover on the magnet field and shed water, smoother steering at speed", "Robot City's Hover Cup ring race is retired. Zip now sends you to Pit Row on Velocity", "The Starlight Lounge bass now thumps, heavier near the speakers", "Other pilots in space are easier to spot: beacons, readable name tags, and ships that pitch and bank", "B.U.R.P.: 67 new recorded lines (fishing, the gun range, races, Velocity, low health, standing around) and a 60-second B.U.R.P. trailer in Codex, Cinema", "Balance: weak guns and staffs hit harder, and bounty rewards were evened out"] },
  { id: 98, title: '2.13.6 · A cleaner Velocity, the Halo Run and fixes', items: ["Velocity driving screen: health, drone, pet, heal and the raid tracker step aside while you drive, and the drive hints fade after ten seconds", "Speed now reads in mph, and the hover cars hum a deep magnetic drone", "Drift, Boost, Use and Camera sit together in the bottom-right corner", "Halo Run: a new race out the east gate, all the way around the planet in the Halo Line, and home through the west gate", "Blacklights over the Halo Line ramps, and the tunnel barrels now run back into the cliff wall", "Your car has a proper floor and footwell, so the road no longer shows through under the dash", "The radio lives in your ship: turn it on at the console by the bridge window. It plays on board and while you fly; everywhere else you hear the normal soundtrack", "The hall viewport now looks out on open space: a field of stars and the odd ship passing by (kept light so phones stay smooth)", "Lab: a live countdown to the next dose, a sign over the vat, and switching recipes no longer throws away finished doses", "Raid tracker button is now a Settings switch (Game tab), off by default. Raid pop-ups still show", "Galaxy map and pause menu fit sideways phones"] },
  { id: 99, title: '2.13.7 · Fire everything, hold to heal, and a shipwright bay', items: ["One Fire button now fires every weapon your ship has fitted. The ammo picker is gone; buy plasma, flak, missiles and EMP as weapon mounts from Brakka or the bridge terminal.", "Hold Heal to top up until full. It only opens a new medkit when it needs one, and keeps the rest banked.", "New Repair button while flying: hold it to patch the hull, 2 cr per point, never more than needed.", "Flight buttons sit where the driving ones do. The radio and the lasers box are gone.", "Brakka has his own shipwright bay in the Zeltac lobby, welding away on a ship up on stands.", "Menus no longer flip through pages. Lists scroll, while the picture and Done always stay on screen. The gun mod bench shows paint, rounds and ordnance together.", "Backpack on a sideways phone: item details sit in two columns, with the buttons pinned.", "The ship hall window shows stars edge to edge, and a CREW QUARTERS door opens onto the crew's bunks.", "Planet name tags in space are now a setting, off by default."] },
  { id: 100, title: '2.13.8 · The Maw fight, rebuilt', items: ["The intro cutscene now plays every time you take on the Maw.", "The Greater Maw is bigger and nastier: bone armour, a crown of teeth, more eyes, glowing cracks and whipping tendrils.", "It fires purple rings now. Its spawns hold the line between you and it, with a red glow so you can see them.", "Your squadron's lasers fly all the way in and burst on its hide. No more name tags; your allies talk over comms instead.", "Not everyone makes it home. B.U.R.P. takes it hard.", "A final phase: the Maw morphs, the squadron forms up around you, and B.U.R.P. offers fight mode. Mega guns, explosions, smoke, and Vega yelling to keep firing.", "Fight comms are a small strip at the bottom of the screen, out of your way.", "The Greater Maw is in the 3D Asset Studio, so you can edit it there."] },
  { id: 101, title: '2.13.9 · Every place has a sound', items: ["Ambient sound everywhere: ship hum and vents, birds on Earth, desert wind on Mezar, surf on the Ocean World, crowd murmur in the Zeltac and the arenas, machines in Robot City, thunder on Zarlich, and the Maw's low groan.", "Rain, acid rain, snow and sandstorms add their own layer outdoors.", "It sits under the music, crossfades as you travel, and has its own Ambience slider in Settings → Sound."] },
  { id: 102, title: '2.13.10 · Lab stations and a steadier garage', items: ["The Lab keeps everything it makes. Switching a recipe moves finished doses to a lab shelf, and Collect empties the shelf and every station into your bag.", "Build up to 3 lab stations, each brewing its own recipe side by side.", "Two-column lists on a sideways phone (like Garage Gus) no longer flip to one column and back when you tap something."] },
  { id: 103, title: '2.13.11 · Lab fixes', items: ["The Lab list no longer jumps back to the top while you scroll.", "Each lab station now shows what its drug does and what a dose costs.", "The Add station row is laid out properly on a sideways phone."] },
  { id: 104, title: '2.13.12 · The real ending', items: ["The Greater Maw's last, morphed phase takes longer to burn down.", "Killing the Greater Maw for the first time rolls a new ending and the credits straight away, with the whole squadron flying home through the wormhole. Afterwards you land in New Jamestown next to Captain Vega.", "On touch screens, the USE button sits in the right-hand button column, and the gun and ammo box moves next to your HP so FIRE never covers it.", "The menu tiles have new icons drawn from the game's own 3D models, and the text no longer spills over the tiles outside fullscreen."] },
  { id: 105, title: '2.13.13 · Voice packs', items: ["B.U.R.P. can now come in more than one voice. When there's more than one voice pack, pick yours in Settings → Sound.", "Behind the scenes: a Script Studio for editing B.U.R.P.'s lines, cutscene captions and the battle radio, and for making new voices."] },
  { id: 106, title: '2.13.14 · Orchestral Mayhem', items: ["The Greater Maw's last phase has its own soundtrack, Orchestral Mayhem, looping until it dies.", "B.U.R.P. cheers you on through fight mode with new lines."] },
  { id: 107, title: '2.14 · The Art of War, remastered', items: ['The opening film for new troopers is back and rebuilt: a burning sunset over the battlefield, smoke columns, real fire, a proper fireball, and a giant stone trooper rising from the rubble.', 'Vega now narrates it out loud, and the space battle has a full sky of stars and nebulae. Replay it from Codex, then Cinema, or skip it with Settings → Story scenes.', 'The Prologue aboard your ship has stars all around every shot.', 'Port Kelp: the side docks now run out to sea instead of into the huts, the fishing docks line up with them, and the lighthouse stands on solid ground.', 'The skeletons on Vector lie the right way, ribs arching over the spine.', 'Phones no longer flash a half-built start card while the game loads.'] },
  { id: 108, title: '2.14.1 · Moon quest fix', items: ['Breathing Room on the Moon can be finished again: moon mites keep dropping O2 Filters until you have all four. Before, they stopped after the first one.', 'The same fix lets Sky City droid chips keep dropping until you have the five the quest asks for.'] },
  { id: 109, title: '2.14.2 · One weapon button, model icons everywhere', items: ['Phones: tap the weapon box to cycle gun → staff → melee. The separate SWAP button is gone and Reload takes its spot.', 'The weapon box stays the same size and in the same place whichever weapon you hold.', 'Every button inside the menu tablet (Ship, Vehicles, Journal, Social, Settings) now has a little icon made from the game\'s own models.', 'If something breaks on a phone, the red error box now lists every error in order, first one on top, so testers can screenshot the real cause.'] },
  { id: 110, title: '2.14.3 · Vega narrates every cutscene, iPhone fix', items: ['iPhones and iPads: the game no longer crashes on load (Safari has no mouse lock, and one line assumed it did).', 'Vega, the voice from the opening film, now reads every cutscene and the prologue out loud. Shots wait for her to finish.', 'Opening film: the stray "And…" is gone, your wingmen fly in formation beside you, the enemy fleet is spread out and mixed, the battle has six kinds of robots, and dropped guns lie flat on the ground.', 'Prologue: the stars are smaller and calmer, and the odd ball of stars around one planet is gone.'] },
  { id: 111, title: '2.14.4 · A real hangar, a proper catch card', items: ['Hangar: the floor pad no longer flickers. Your selected war vehicle now turns on a lit turntable, with a gantry crane overhead, a tool wall, a red tool chest, tyre stacks, fuel drums, a fuel pump and guide lights to the launch door.', 'Fishing: the fish you caught now swims in front of its card, and the card waits for you to tap Continue (or press Enter or E).', 'Phones: the USE button can no longer land on top of the radar.', 'New drawn icons for the camera and repair buttons. The ship and the car share the same camera icon.'] },
  { id: 112, title: "2.14.5 · The Angler's Den, rooms that grow, Vega's film", items: ["New ship room: the Angler's Den. Mount your catches on 12 wall plaques, each showing the fish and your best length. Take one down any time to get the fish back. It also has a rod rack, an armchair and a big aquarium.", 'Upgraded ship rooms now look upgraded. Lv 2 and 3 each add a themed prop, Lv 4 hangs a banner and a second light, and Lv 5 adds gold trim and a crest at the door.', 'Ship corridor: the hull posts no longer stand in doorways, and the crane hook that was floating in the hall is back inside the hangar.', 'Fishing: the Bug Pond, Fern Pond and Coolant Canal are bigger, your cast always lands in water, and Coil in Robot City moved back from the dock.', 'Opening film: Captain Vega is the hero now (you are a fresh recruit), and the soldiers that were standing inside her are gone. Her ship flies the film\'s space battle.', 'Prologue: the ball of stars is gone, the stars are dimmer so the planets stand out, the thing behind Vector is now the Watcher rising out of the dark, and Drome\'s flagship wears a setting-sun sigil instead of a big red dot. With voice off, the prologue no longer stalls on its first line.'] },
  { id: 139, title: "2.19.8 · Inside the Roxy", items: ["Cinema seats face the screen, and moviegoers sit in about ten of them", "You walk on the tiered floor instead of sinking through it, and the seats sit on their tiers", "The Roxy has just its marquee out front: the old building sign behind it is gone, and the street lamp no longer stands in the doorway"] },
  { id: 140, title: "2.19.9 · Roxy touch-ups", items: ["The Roxy marquee and reader board no longer overlap or flicker", "The red carpet sits above the sidewalk instead of flickering through it", "Moviegoers sit with their legs angled down instead of poking through the seats"] },
  { id: 141, title: "2.19.10 · Load fix", items: ["Fixed a crash on load for saves that tracked a quest which no longer exists"] },
  { id: 142, title: "2.19.11 · Posters & graffiti", items: ["Eight poster designs now hang on walls across the universe: bars, the underground, ship halls and town buildings", "Spray-paint graffiti tags turn up on walls too"] },
  { id: 143, title: "2.19.12 · Grub's Bar", items: ["The Undercroft bar is now Grub's Bar, with a cyan neon sign", "Hanging chain lamps, a back wall of glowing bottles, beer taps and mugs on the counter", "Tables with red stools, arcade cabinets and junk on the floor"] },
  { id: 144, title: "2.19.13 · Ship fixes", items: ["The galaxy map railing on the bridge is solid now, with the opening at the front", "Crew no longer walk through the front of the hall by the bridge"] },
  { id: 145, title: "2.19.14 · Fewer posters", items: ["Posters and graffiti now only appear on Earth, and fewer of them"] },
  { id: 146, title: "2.19.15 · Grub's Bar in the Underworld", items: ["Grub's bar in the Underworld gets a cyan neon sign, glowing neon bottles, bulb chandeliers on chains, beer taps and mugs", "Regulars sit at the bar and at two new tables; dark floor with junk scattered about"] },
  { id: 147, title: "2.19.16 · Crew for hire", items: ["Seated people in the theatre and the bar now sit properly, with their knees bent at 90°", "More regulars in the Underworld: a couple eating in a booth, a deal going down in a new booth, two talking business", "Hire crew from Grub: a Runner fetches Lab materials, a Cook brews extra doses, a Dealer sells your product for credits", "One crew slot to start, two at level 15, three at level 30. Crew can get killed on the job, so check back at the bar for replacements", "Manage your crew from the Lab terminal on your ship"] },
  { id: 148, title: "2.19.17 · The Glonk Trio", items: ["A cantina band plays on a little stage in the Underworld: a keytar, a theremin and glowing drum pods", "The Underworld now plays Glinky Glonky and Crooked Clarinet"] },
  { id: 149, title: "2.20 · Hand-made UI", items: ["New hand-drawn pixel windows and buttons: framed panels with brass rivets, chunky bevelled buttons that press down", "Every menu uses the game's pixel font", "No more see-through glass panels or emoji in menus"] },
  { id: 150, title: "2.20.1 · Save fix", items: ["Fixed a crash on the start screen when a cloud save loaded read-only data"] },
  { id: 151, title: "2.20.2 · iTab 15 Pro", items: ["New Settings → Graphics → Menu colour: Plum, Navy, Ember, Moss, Steel or Crimson", "The menu tablet is a black glass slab with a metal rim, the menu sits on its screen with scanlines, and the bezel says iTab 15 Pro + Ss Extreme", "Tablet tiles use the hand-made buttons, with no emoji"] },
  { id: 152, title: "2.20.3 · Steel and a round map", items: ["Steel is the default menu colour", "The minimap is round again, with a pixel ring in your menu colour", "The tablet now draws above the HUD, so the map no longer pokes through it"] },
  { id: 153, title: "2.20.4 · A real Worm Hole", items: ["The Worm Hole in the Angler's Den is a dark alloy containment collar with six glowing emitters, a hovering lens ring and a swirling starry event horizon; the sign is gone", "The detail panels on the bridge side walls no longer clip into the wall"] },
  { id: 154, title: "2.21.0 · Boutique drugs", items: ["Glowing ingredients now grow out in the worlds: Glowcaps, Void Shards, Luma Beetles, Frost Salt, Nebula Moss, and the very rare Star Nectar. Walk up and harvest them; they regrow after a while.", "A new Boutique Bench in your Lab refines two raw ingredients into one extract, then lets you design your own drug: a name, a liquid colour, up to three extracts, and the five sliders. Extracts set how high each slider can really go.", "Your Chemist level rises slowly as you refine and brew, unlocking more extract slots and higher caps. F grade will not sell; S grade spreads by word of mouth and sells for more.", "Your saved recipes and their sales are on the bench Stats tab. The house brews stay as they were."] },
  { id: 155, title: "2.21.1 · Brewing that makes sense", items: ["You can brew with just one extract now. The Potency/Purity/Glow sliders are gone: you cook with Heat, Stir, Pressure, Steep and Cut, and every mix of extracts has its own hidden sweet spot. Maxing everything burns the batch.", "Each slider gives you a hint like \"runs hot\" or \"thin\", and the hints and grade guess get sharper as your Chemist level rises.", "A spinning inhaler at the bench shows your drug: its liquid takes your colour, glows, bubbles with strength, and goes cloudy when it is impure."] },
  { id: 156, title: "2.21.2 · The Glonk Quartet", items: ["The cantina band in Grub's bar has a bigger stage with a lighting truss, sweeping colour spotlights, a glowing backdrop and a singer up front.", "The music now comes out of the band's speaker stacks: louder and clearer as you walk up, panned toward the stage, and muffled across the room."] },
  { id: 157, title: "2.21.3 · Fixes", items: ["Taking a drug shows a proper hand on the inhaler instead of the spongy block.", "The Comet Bar in the Starlight Lounge moved over so the elevator is no longer hidden behind it."] },
  { id: 158, title: "2.21.4 · A real crew", items: ["Your crew now stand in your Lab doing their jobs: the cook at the flask bench, the runner sorting crates, the dealer counting cash. Walk up and talk to them.", "Every hire has a trait (Careful, Quick, Greedy, Lucky, Loyal or Reckless), a backstory and their own look.", "Crew are paid a wage out of your credits each shift. Paid crew grow loyal and more careful. Go unpaid too long and they quit.", "Skills grow with shifts, up to five stars. Bad nights often just wound them for 30 minutes instead of killing them.", "The Crew panel shows each person's loyalty, pay, earnings and last shifts, with Bonus, Lay low and Fire buttons."] },
  { id: 159, title: "2.21.5 · Street dealers", items: ["Every outlaw world now has a street corner under a lamp post, with someone looking for work. Hire them and they sell your Lab product there every shift, sending the credits home.", "Rivals can kill a street dealer, and some rat you out: the Marshals hear your name, your outlaw rep jumps and you may go Wanted. Either way the corner is empty until you hire again.", "With a Dealer on your crew you can set up street dealers from the Crew panel (Street dealers button) without flying there, for a bigger fee. Careful and Loyal dealers last longer."] },
  { id: 160, title: "2.21.6 · Dealer heat", items: ["Every street dealer has a heat meter. Each sale adds heat, and the hotter they run the more likely rivals hit them or they rat you out. You get a warning when one runs hot.", "Tell a dealer to Lay low from the Street dealers list or by talking to them on their corner. They stop selling and cool off fast."] },
  { id: 161, title: "2.21.7 · Loading bars, faster Earth", items: ["A loading bar shows while the game starts up and every time you travel to another world, so on slower phones you know it is working.", "Earth loads about a third faster: the scenery merge does far less work, and the ground is reused when you come back to a world you already visited."] },
  { id: 162, title: "2.21.8 · Bench, stats and fixes", items: ["The Boutique Bench keeps its scroll position when you change something, so on phones it no longer jumps back to the top.", "The Stats tab is rebuilt: each recipe shows its colour, grade, street rep stars (up to five, by doses sold), credits earned, current price and how far to the next star.", "Lab crew hold their hands properly now (hands were floating off the arms), and the dealer has their own counting table out of the way of the consoles.", "No more muzzle flash when you pull the trigger somewhere you can't fire."] },
  { id: 163, title: "2.21.9 · Real laser bolts and the Black Galaxy Beam", items: ["Shots are no longer thin lines. Every gun fires a glowing bolt with a white-hot core inside a coloured halo and a bright slug racing down it.", "New gun: the Black Galaxy Beam (Seer Ixa on the Zeltac, level 18). Hold the trigger for a steady beam of drifting black starfield that throws off sparkles and hums low while it fires."] },
  { id: 164, title: "2.21.10 · An honest loading bar", items: ["The travel loading bar now paces itself on how long that world actually took to load on your device last time, instead of a fixed timer.", "The graphics are warmed up behind the loading screen before it lifts, so the long freeze right after landing (worst on Earth, on phones) happens while the bar is still showing, and it only fills once the world is ready.", "The startup bar stays up until the first frame is actually drawn."] },
  { id: 165, title: "2.22.0 · The beam guns", items: ["Beams are half as wide and now come straight out of the barrel, swinging with you as you turn.", "Six beam guns, each with its own body, beam, sparkles and hum, sold by Seer Ixa on the Zeltac: Black Galaxy Beam (Lv 18), Solar Lance (Lv 30), Glacier Ray (Lv 45), Venom Stream (Lv 60), Crimson Ray (Lv 80) and the Lvl 100 Darkbeam, a solid black beam with a white edge like the dark saber."] },
  { id: 166, title: '2.22.1 · New ship track', items: ['"Wistful Drift" joins the ship playlist.'] },
  { id: 167, title: '2.22.2 · More drug materials', items: ['Six new materials: Ember Root, Sky Pollen, Rust Lichen, Tide Pearl, Ghost Orchid and Quasarite. Fort, Sky City and Vector now grow them too.', 'A Drug Room Box in your Lab. Tap "Dump materials" to store everything you gathered; the Boutique Bench uses the box first.'] },
  { id: 168, title: '2.22.3 · Better laser shots', items: ['Laser bolts glow in their gun colour, with a soft spark racing down them instead of a ball.', 'Alien guns blow out a soft glowing ring instead of a hard circle.', 'Twelve new synthwave laser sounds, picked at random each shot.'] },
  { id: 169, title: '2.22.4 · Drug box fix', items: ['The Drug Room Box list no longer stacks up or leaks into other menus, and each material sits on one line.'] },
  { id: 170, title: '2.22.5 · One sound per gun', items: ['Each gun now always fires with its own laser sound instead of a random one.'] },
  { id: 171, title: '2.22.6 · Dev unlock', items: ['Testing shortcut: tap the version line on the title screen 7 times quickly to unlock everything.'] },
  { id: 172, title: '2.22.7 · Dev unlock covers everything', items: ['The 7-tap unlock now also builds and maxes every ship room, and unlocks all armor, furniture, pets, saber mods, ship parts and paints, the drone, race cars and war vehicles.'] },
  { id: 173, title: '2.22.8 · Dev unlock stocks items', items: ['The 7-tap unlock also fills your pack with 50 of every item and material, for testing drugs and crafting.'] },
  { id: 174, title: '2.22.9 · Take your own drugs', items: ['Drugs you brew now have a Take button in your bag, and on the Recipes tab of the Boutique Bench.'] },
  { id: 175, title: '2.22.10 · Aranus Man pages', items: ['The Aranus Man comic pages show up again.'] },
  { id: 176, title: '2.22.11 · Drug asteroids and crate furniture', items: ['Green-glowing asteroids in the belt drop drug materials when you break them, sometimes even Star Nectar.', 'Furniture is no longer bought. Every piece is found in salvage crates, on planets, in space and in boarded ships.'] },
  { id: 177, title: '2.22.12 · Cleaner iTab', items: ['Health, ammo, quest and clock panels hide while the iTab is open, so nothing sits on top of it.'] },
  { id: 178, title: '2.22.13 · Smooth melee', items: ['Melee weapons and sabers swing in a smooth flowing arc. Hold attack and the blade carves a continuous figure-eight, one strike per pass.', 'Nunchucks, Poison Claws and Driller Claws are two-handed now: one in each hand, swinging in turn.'] },
  { id: 179, title: '2.22.14 · Two-handed weapons', items: ['Twin Master Swords: one sword in each hand.', 'Frost Staff and Reaper Scythe are held across your body in both hands, and the swing turns into a spin.'] },
  { id: 180, title: '2.22.15 · Enemy plasma bolts', items: ['Enemy shots are glowing plasma bolts with a coloured halo and a comet tail, and they flash where they land. Coloured lobbed shots glow too.'] },
  { id: 181, title: '2.22.16 · Drug timers and a tidier bench', items: ['Brewing takes time now: a batch cooks for 1.5 to 3.75 minutes depending on how many extracts it uses, and keeps cooking while you play elsewhere. Come back and Collect.', 'Refining takes 25 seconds per extract, with a Refine All button that queues the lot.', 'The bench shows what is cooking with a progress bar at the top, and the design page is split into Look, Extracts and Cook sections with a shorter summary line.'] },
  { id: 182, title: '2.22.17 · Zeltac Mall', items: ['The Zeltac Plaza is a little mall now: nine glass-fronted shops with neon signs, shelves of goods and awnings line both walls.', 'Kiosks, benches, planters with trees, lit walkways, hanging banners, a starlit skylight and a mall directory by the airlock.'] },
  { id: 183, title: '2.22.18 · A tighter, livelier Underworld', items: ['The Underworld basement is about a quarter smaller, so it feels packed instead of empty.', "Grub's bar is dressed up: a lit back bar of bottles, beer taps and glasses, red bar stools, neon signs, a dartboard, a rug and steaming pipes."] },
  { id: 184, title: '2.22.19 · Zeltac decks, dressed', items: ['The working Zeltac decks are a little tighter and better organised: pillars with lit caps, wall lights, trim borders, ceiling beams and hanging lamps, and a sign for each deck.', 'Market lanterns and produce crates, grow lights and a water channel in Hydroponics, a prize counter and couches in the Arcade, hazard stripes, steam vents and barrels on the Engine Deck, bonfires and totems in the Alien Quarter, reading desks in the Archive, and a captain\'s dais on the Bridge.'] },
  { id: 185, title: '2.22.20 · Planned plaza, a real bridge window, and the big shipment', items: ['The Underworld is back to full size; the Undercroft deck is the one that shrank.', 'The Zeltac Plaza is laid out properly: a stone-columned Zeltac Bank with a vault door and teller glass, a Mission Center with a holographic job board, the Zeltac Exchange stall, a clinic with a red cross, and a sealed blast door to the Alien Quarter. The plywood fronts, loose crates and floating banners are gone.', 'The mall skylight and the bridge window are real openings now: real stars, planets, drifting asteroids and passing ships outside.', 'The bridge has a crew at its stations. Quartermaster Dax wants a big drug shipment, and the Marshals crash the handover.'] },
  { id: 186, title: '2.22.21 · Straight benches', items: ['The mall benches sit straight now, facing the hologram, with legs and the backrest behind the seat.'] },
  { id: 187, title: '2.22.22 · Velvet ropes', items: ['The bank rope is now real velvet rope that sags between brass posts, with the way to the doors left open.'] },
  { id: 188, title: '2.22.23 · Skylight open', items: ['The mall skylight is actually open now: look up to see the planet, the moon, asteroids and passing ships.'] },
  { id: 189, title: '2.22.24 · Seats taken', items: ['Six guests now actually sit on the Starlight Lounge VIP couches with drinks, instead of sinking into them.'] },
  { id: 190, title: '2.22.25 · The Hotbox', items: ['The Undercroft back room is now the Hotbox: rainbow haze, people smoking on cushions, and a contact high just from walking in.', 'Knuckles only lets Outlaws (rep 40+) past the curtain.', 'Duke Ferro (2.5×) and Madame Opal (3×) buy S-grade boutique drugs, and nothing less.', 'The Fence moved out to a corner table on the main floor.'] },
  { id: 191, title: '2.22.26 · Tired neon', items: ['The Grub\'s Bar sign stays lit now; only a couple of worn-out letters flicker.', 'The hooded types in the Undercroft booths by the door actually sit on proper low benches now.'] },
  { id: 192, title: '2.22.27 · Darker, danker Undercroft', items: ['The Undercroft is darker now, with a low smoky haze over the whole floor, puddles, drips and slime on the walls.', 'The band is real musicians now: a drummer on a riser behind a full kit, guitar, bass and keys players, amps, a curtain, and a lighting truss with sweeping coloured spots. Velma has a mic stand.'] },
  { id: 193, title: '2.22.28 · Vixen Glippo', items: ['The Undercroft band plays Awzil Nap from the stage amps, louder as you get close.', 'A round stage in the corner with velvet curtains, a curved lighting truss, a mirror ball and footlights. The guitars became a space sax and a space trumpet.', 'Vixen Glippo, an alien singer, has taken the mic. Her ex Krenn Vosh is in apartment 9C off the left wall: take her job, go in with fists only, and knock him out. After that you can get to know her.', 'The poker players no longer stand inside the table.'] },
  { id: 194, title: '2.22.29 · Vixen, up close', items: ['Vixen Glippo has a new look: pink skin, a small pretty face, long wavy purple hair with sparkles, and a red dress.', 'The stage now has pink haze and fog machines, a VIXEN GLIPPO neon sign, string lights, speaker stacks, monitor wedges, café tables with candles, and the band in shades and hats.', 'The quest plays out properly now: Vixen invites you over to 9C, Krenn walks in, says his piece, and the fistfight starts.'] },
  { id: 195, title: '2.22.30 · Tubes and the airlock', items: ['The Zeltac elevators are pneumatic tubes now: glass, chrome rings, a glowing intake pad and air rushing up. Picking a floor sucks you up with a whoosh.', 'The plaza airlock is a real airlock: a heavy arched frame, striped blast doors with portholes that part as you walk up, spinning beacons, a hazard strip and status panels.', 'Vixen\'s skin is smooth, and her neon sign is out of the wall.'] },
  { id: 196, title: '2.22.31 · A night at Vixen\'s', items: ['Vixen only invites you up if you bring her an S-grade boutique drug.', 'The 9C scene is longer and funnier: you get high with her, black out, and wake to Krenn pounding on the door (she\'s in red shorts by then). He barges in, you trade words, then fists.', 'After the knockout she thanks you properly and runs off to play her next set, back in the red dress.', 'Your combat drone sits out the scene and the fight. The 9C door moved to a clear spot on the left wall, and the bar sleeper no longer melts into the counter.'] },
  { id: 197, title: '2.22.32 · Booth legs', items: ['The hooded types in the Undercroft booths by the elevator sit forward on the bench, so their legs no longer clip into the seats.'] },
  { id: 198, title: '2.22.33 · Pet fish', items: ['The Angler\'s Den aquarium takes your catches: walk up and drop a fish in, and it shrinks to fit and swims laps with the others. Up to 16, and you can take them back out.'] },
  { id: 199, title: '2.22.34 · Tank upgrades', items: ['The aquarium starts as a small desk tank for 4 fish. Upgrade to a Long tank (8), Show tank (12) or Grand aquarium (16).', 'Buy decorations: pebbles, weeds, a rock arch, a bubbling treasure chest, a castle, a diver and glow lights.', 'Fish swim slower, and the old decorative fish are gone.', 'The Zeltac airlock doors are solid now.'] },
  { id: 200, title: '2.22.35 · A little favour', items: ['Stardust Books in the mall sells Aranus Man comics from Earth, including the signed copy.', 'Don Klunkleone eats in the new McKlunkies booths in the mall. Nobody fences contraband (drugs aside) on any world until you do his little favour for him: Glorbo Fishwhistle in Hydroponics.', 'Pour the Don\'s sauce on a drug you made and let Glorbo try it. Then the hydroponics fish tank is yours, and your fish replace the house fish.', 'McKlunkies no longer sells drugs. The back counter only buys contraband.', 'The HUD fades away when you stand still and comes back when you move.', 'The Zeltac airlock is sealed with glass, and the stray sign in front of it is gone.'] },
  { id: 201, title: '2.22.36 · McKlunkies', items: ['McKlunkies moved to the mall\'s back wall, with a giant waving Klunky out front and a door into a full restaurant: order counter, diners, and Klunky\'s Fun Zone play place.', 'Lulu Sprinkles runs the play place. You can romance her and make her your partner.', 'Don Klunkleone now sits in a dim private corner at the back of the restaurant.', 'Aquarium fish swim slower and in different directions.'] },
  { id: 202, title: '2.22.37 · Fixes', items: ['The Don\'s sauce is poured right at Glorbo if you have any drug, no inventory step. Glorbo now stands in front of his tank.', 'Klunky\'s arms bend the right way. The McKlunkies interior no longer flickers or wobbles.', 'The Don\'s corner has velvet walls, sconces, a rug, his portrait, a bar cart and cigar smoke.', 'The gaps beside the Zeltac airlock are glass now, and solid.'] },
  { id: 203, title: '2.22.38 · B.U.R.P. and shorter films', items: ['The opening film is shorter and the narration runs line to line without long pauses.', 'In the Maw battle, Captain Vega only speaks her first line out loud.', 'B.U.R.P. has a wall terminal on the ship with a little talking head, and new characters get a hologram B.U.R.P. who walks them through the basics.', 'About half of B.U.R.P.\'s lines were rewritten to be friendly instead of sassy, with new voice clips.', 'McKlunkies: rebuilt play place, solid painted walls and a real door on the Don\'s room, no more flashing floor or rug.'] },
  { id: 204, title: '2.22.39 · Ocean World overhaul', items: ['The submarine is gone. Port Kelp has three new piers and a space kayak rental shack (40 cr).', 'Paddle the kayak anywhere, then climb out at a pier or the shore.', 'You can now fish anywhere you face open water, on foot or from the kayak, on every water world.', 'Bubble City is now a sealed miniature dome. Use the Shrink-o-Matic beside it to shrink down and enter a full-size city inside.'] },
  { id: 205, title: '2.22.40 · Inside Bubble City', items: ['The Low Tide: a seedy strip with a dealer, Crabby\'s Pawn (a fence), and Rizzo, who needs a stolen TV sold.', 'Coral Heights: an apartment tower with an elevator and six floors of neighbours to knock on. Rent apartment 6B from Mrs. Krill: a porthole, a TV, and a bed you can lie in to watch it.', 'A lost hamster in the coral park follows you once you pick him up. Find his owner upstairs.', 'Murder in the Burbs: help Detective Clam find out who drowned Gerald.', 'Dome Control (flip day and night) and Reel Deal Tackle, which sells fishing waders and an angler vest.'] },
  { id: 206, title: '2.22.41 · Docks and kayak sunsets', items: ['The piers now stand above the water and you can walk on them. The kayak shack sits at the root of the main pier, with a spinning kayak sign.', 'Fishing from the kayak slowly turns the sky to a golden sunset, dims the water and lays a glittering path toward the sun.', 'Crates, nets, gulls, lily pads and buoys around Port Kelp. Benches, graffiti, puddles and litter in Bubble City. Your flat has a rug, posters, a beanbag and a fish bowl.', 'The Dome Control lever now dims the city lights.'] },
  { id: 207, title: '2.22.42 · Bubble City, the real city', items: ['Bubble City is now five glass domes on the seabed joined by glass tunnels with moving walkways.', 'Bubble Central: the plaza, the Founder Fishwick fountain, food carts, a transit map, and the way out.', 'The Low Tide: a neon street with a pawn shop, the Barnacle Bar, a tattoo parlour, an arcade, Rizzo\'s van full of TVs, steam vents and a burning barrel.', 'The Burbs: a cul-de-sac of houses with porches, fences, mailboxes, cars, a playground and sprinklers. And a murder.', 'Kelp Gardens: grow beds and Dome Control, a tower with a spinning radar. Coral Heights: three apartment towers, Reel Deal Tackle and the coral park.', 'Outside the glass: kelp forests, rocks, light shafts, fish schools and a whale drifting over the city.', 'People walk facing forward now, and street dealers only sell street drugs.'] },
  { id: 208, title: '2.22.43 · Proper seagulls', items: ['The spinning white blobs on the piers are now real seagulls perched on the posts. They look around now and then instead of spinning.'] },
  { id: 209, title: '2.22.44 · Bubble City glow-up, waders and the Solar Lance', items: ['Bubble City: sliding glass doors at every tunnel mouth, real textures on floors, walls and roofs (tile, brick, siding, shingles, grass, pavers, grates), new peaked roofs, and no more swimming floors', 'Night follows your real clock: the domes go dark and blue, and the lamp posts light pools on the ground', 'Signs have borders, rivets, glow and sub-lines. The Low Tide got awnings, AC units, cables, posters and trash, and Rizzo\'s van was rebuilt with its TVs facing the street', 'Apartments: the street door only shows in the lobby, the flat has wood floors and wallpaper, and the porthole looks out on the sea with kelp, fish and light rays', 'More life: a backyard BBQ, a dog running round the Burbs, a busker\'s guitar case in the plaza', 'Reel Deal Waders now look like waders (fish bite 40% faster) and the Pro Angler Vest is a real vest (rare fish 60% more likely)', 'The Solar Lance now sings the Staff of the Setting Sun\'s chord, held for as long as you fire', 'You can no longer walk through the small blue bridge consoles on your ship'] },
  { id: 210, title: '2.22.45 · Rain on the water, jumping off docks', items: ['Pip, the kid in Bubble City, is now Young Porkins, and he is a lot rounder', 'The Solar Lance is now a smooth, bright light-ray tone instead of a buzzy chord', 'The ammo box shows the gun name and what it fires (rounds, shells, energy, charge, rockets, bolts) with no more "/ ∞"', 'Rain makes rings and spray on the ocean and on Velocity\'s road', 'Jump off a dock and you fall, splash, sink a little and bob back up', 'Port Kelp: the nets are off the docks, the gulls perch on crates and decks instead of the rope rail, the middle of the island is clear, and the beached boats are now proper fishing boats out on the water with a fisher in each'] },
  { id: 211, title: '2.22.46 · The Low Tide opens its doors', items: ['Every Low Tide storefront has a door now, with a real room behind it: Crabby\'s Pawn, the Barnacle Bar (drinks that heal, and darts for prize money), Ink Squid Tattoo (five tattoos to collect), the Fish Fry Arcade (a playable fish-tapping game with a high score, plus a claw machine crab), the 24/7 Shellmart (snacks and medkits) and the Karaoke Clam (sing to the beat for tips)', 'Fishing boats rebuilt: proper hulls, the fisher holds the rod, and every so often hauls a fish out of the water', 'With a jetpack you can blast up out of the water from swimming', 'Tunnels: no more dome ribs or base rings across the walkways. The plaza map faces the plaza', 'The far-off apartment and shop buildings sit under their own glass domes'] },
  { id: 212, title: '2.22.47 · Boats you can sit in, proper Low Tide shopfronts', items: ['Fishing boats have a solid deck now, so no more water sloshing inside', 'Swim up to a boat and press E to sit on the bench beside the fisher, then E again to hop back into the water', 'Low Tide shops got real panel doors with portholes, handles, lamps and OPEN signs, plus framed display windows', 'Every shop inside now has a rug, wood trim, posters, potted plants, a spinning ceiling fan and a regular hanging around'] },
  { id: 213, title: '2.22.48 · Marisol and Peanut', items: ['Bring Peanut home and Marisol invites you into her flat in 4B: a couch, TV, lava lamp, kitchenette, bed, string lights, and Peanut running on his wheel', 'Talk to her inside to ask her along. She becomes a companion who follows you and shoots what you shoot (send her home from the Companions list)', 'Or get high together: a rainbow haze fills the room, then it fades to morning with full health', 'Coral Heights has real doors now: glass double doors at the entrance and in the lobby, and panel doors with number plates, peepholes and lamps in the halls'] },
  { id: 214, title: '2.22.49 · Marisol works for you', items: ['Marisol no longer follows you around. Ask her to sell for you and she joins your ship crew as your Dealer, working the Lab: she takes doses off the shelf and sells them, and you get the credits', 'She starts at three stars and is Loyal'] },
  { id: 215, title: '2.22.50 · Clear hallways', items: ['Coral Heights: the lobby desk no longer appears on every floor in front of the doors. It stays in the lobby, out of the way'] },
  { id: 216, title: '2.22.51 · Warp gates and a tighter intro', items: ['The opening trailer cuts the long quiet stretches between Captain Vega\'s lines', 'New Jamestown: the Forest of Life and Super Swift Arena signposts are now warp gates, with swirling portals, glowing runes and a flash as you step through', 'The Phantom car has a sleek nose and headlights instead of a giant pyramid', 'Settings: the Filter (PS1 Glow, Crisp Toon, Neon Night, Golden Hour...) now also tints the HD Stylized and Semi-Realistic looks, not just the PS1 ones'] },
  { id: 217, title: '2.22.52 · Steam, a sax and a victory lap', items: ['Energy and beam guns now burn their charge even with the Unlimited Clip, and reload on their own when empty with a tssshh of venting steam', 'The Unlimited Clip shows ∞ on the guns it still covers', 'Phones: the Reload button is gone (it still turns into Block with a melee weapon)', 'Vixen Glippo: the 9C door sat inside the wall. It is a proper door on the wall now, with a pink lamp', 'After you knock out Krenn Vosh you can piss on him', 'The Undercroft sax player holds his sax properly: mouthpiece at his lips, hands on the keys'] },
  { id: 218, title: '2.22.53 · Fishing from the boat', items: ['Sit in a fishing boat and press E to fish off the side next to the fisher. Move or jump to hop out (no Get Up button any more)', 'The opening trailer\'s song now plays straight through under the shots instead of skipping, and the one-second shot after the first line is gone', 'Peanut runs forwards now, in the park and when he follows you. His wheel at Marisol\'s is a proper 3D wheel and he runs along it the right way', 'The 24/7 Shellmart is no longer blinding: darker shelves, muted goods and softer lights', 'Galaxy map: Ocean World now lists Bubble City too, so you can go straight to the city'] },
  { id: 219, title: '2.22.54 · Peaceful townsfolk', items: ['Alien shopkeepers and townsfolk (bug folk, spearmen) no longer carry spears, shields or staves. Enemies still do'] },
  { id: 220, title: '2.22.55 · Spearmen walk', items: ['The green spear aliens (enemy spearmen, and townsfolk like Zib) now swing their legs and bob when they move instead of sliding'] },
  { id: 221, title: '2.22.56 · Unarmed crowds, really', items: ['The station crowd, the Undercroft regulars and every city crowd now leave their spears and shields at home too', 'Phones: the Reload button is really gone now'] },
  { id: 312, title: 'Shield fix', items: ['The shield no longer sits on screen while you drive in Velocity (or fish, or use the tablet) with a melee weapon out'] },
  { id: 313, title: "2.23.48 · Phil's big fix list", items: ['Minimap: always the arrow now, glowing uranium green', 'Fishing: a lure that lands on dry ground catches nothing', 'Velocity: the ramp down no longer stair-steps the car', 'Ship: 6 floor, wall and ceiling styles each for the flight deck and the hallway (Interior styles panel on the flight deck)', 'Starlight Lounge: the seated crowd sit properly on the couches facing the table, and the robot waiters carry a serving tray', 'Ocean world: Mayor Blub floats above the ground, the fishers hold their rods properly, and the Burbs murder scene has a chalk outline, evidence markers and crime tape', 'Marisol and Quartermaster Dax no longer offer drug jobs to Marshals, and Marisol\'s hamster wheel is back', 'Anyone lying on the ground can now be peed on (except the drunk in the Undercroft)', 'New song discovered pop-up', 'Mile Down: the bar music plays through the back rooms', 'Marshals: a 3D badge you flash from your wallet, a tougher office, informants you can hire, and the stolen TV case can end with three arrests and a medal'] },
  { id: 314, title: '2.23.49 · Boat fishers', items: ['The fishers in the ocean world boats really sit on the bench now and hold the rod in their own hands (no more stray arm sticking out of their lap)'] },
  { id: 315, title: '2.23.50 · Cleaner minimap', items: ['The live minimap no longer shows fireflies, rain, sparks or other effects', 'Removed the little winding crown on the minimap watch (the pill-shaped thing)'] },
  { id: 316, title: '2.23.51 · Ready for the cast', items: ['The game can now play real voice-actor recordings for every character line, as they get recorded'] },
  { id: 317, title: '2.23.52 · Helmet radio', items: ['Recorded voices for helmeted characters and battle radio play through a light comms filter'] },
  { id: 360, title: '2.23.95 · New Blork Studios intro', items: ['The game opens with the new Blork Studios logo, drawn by Phil: the white-lined octopus rises out of the dark under soft light, Blork brushes on and studios fades up. Click or press a key to skip.', 'Loading bars are gone. A white loading with dots that count up and back down shows while the game starts and when you travel.'] },
  { id: 359, title: '2.23.94 · Vask drops his loot where you can reach it', items: ['Commander Vask dies on his island in the lava, so his loot now lands on the edge of the pit on your side, where you can walk up and grab it'] },
  { id: 358, title: '2.23.93 · Nobody walks outside your ship', items: ['Crew and other characters can no longer appear outside the Setting Sun and walk in through the hull; anyone outside the ship is kept out of sight until they are back inside', 'Your pet arrives next to you on every trip instead of walking in from where it was on the last world'] },
  { id: 357, title: '2.23.92 · The battlefield doubles, the walker rains rockets', items: ['The Ironrock battlefield is twice as deep with five sectors to hold, plus bunkers, wrecks, craters, wire and roaming Drome tanks', 'Gunners and a flak gun now fire from the Ironrock ramparts', 'The siege walker raises shoulder rocket pods and rains rockets on red circles; step outside the circle and you take no damage', 'The sky battle flies real ships: Drome Raiders, Drome Cutters and The Eclipse against our cruisers and Setting Sun fighters', 'New battle sounds: crunching blasts, far rumbles, lasers, fighter flybys and wrecks hitting the ground', 'Mile Down: the bar has crowd chatter, and you can hear a drill and screams behind the lab door until it opens'] },
  { id: 356, title: '2.23.91 · Ironrock fixes, big explosions, the sky battle', items: ['Walking through the gate no longer throws you up onto the wall walk.', 'No more invisible walls: hidden enemies were still pushing you around.', 'Each lift has steel doors with a lit frame, and a lift house up on the tower top so the way down is easy to spot.', 'Windows, the Med Bay cross and the Med Bay shelf no longer flicker.', 'The second lab computer faces its chair, and the mess hall soldiers hold their mugs.', 'Grenades, shells and barrages now go up in big fireballs with smoke, debris and a shock ring, like the Maw battle.', 'The fleet battle overhead now shows through the haze, with flashes in the sky, burning wrecks crashing into the field and distant booms.', 'Drome units stay out on the battlefield instead of piling up at the fort.', 'The fort intro shots were re-aimed so nothing blocks the view.'] },
  { id: 354, title: '2.23.89 · Softer haze, no labels', items: ['The haze over the Front is now soft drifting dust that rolls in on the wind and thins out as you walk into it, instead of solid smoke blobs.', 'Took down the GUNSMITH plate on the ship gun bench and the name plaques around Fort Ironrock.'] },
  { id: 352, title: '2.23.87 · Cover, fog and a fuller fortress', items: ['Squads on the Front take cover behind sandbag walls, concrete blocks, burnt-out tanks and log barricades. They sit with their backs to it, then stand up to fire over the top.', 'Dust and drifting smoke hang over the battlefield, thickest out at the Front and lighter inside the walls.', 'Every room in Fort Ironrock has more in it now: hanging lamps, pipes, a supply shelf and desk in the Med Bay, a card table in the Barracks, a drinks cooler and TV in the Mess Hall, ready benches and lockers in the Muster Hall, a workbench and dummy in the Armory, and a specimen tank and robot arm in the Lab.', 'The ship gun bench faces into the room and shows your gun on open cradles, with no glass case.', 'The slot machine buttons sit on their own ledge and are no longer covered by the screen housing.', 'The radio plays songs only for now, and skipping to the next or previous song starts playing it.'] },
  { id: 350, title: '2.23.85 · The Front fights back and forth', items: ['Our squads muster in the Muster Hall, march out through the Sally Port and go over the top. Drome squads come out from their side to meet them.', 'The Front has three sectors, south, centre and north, each with a line that moves as squads win or lose. A strip at the top of the screen shows who holds each one.', 'The wounded fall back to their trench, patch up and go out again, and reinforcements stream in for whichever side is losing.', 'Get on a heavy MG and the Drome send runner squads straight at your nest, with shield runners and lieutenants mixed in. Kill streaks pay bonus XP.'] },
  { id: 348, title: '2.23.83 · Fort Ironrock rebuilt as a fortress', items: ['Ironrock is now one walled citadel with corner bastions, a gatehouse and a rampart you reach by the lifts in the courtyard.', 'Every room has a job and its own look: Med Bay and Barracks, Mess Hall, Muster Hall, Command Hall with a live war table, Armory, Research Lab and the Motor Pool Hangar.', 'The Sally Port in the west wall leads to the Front, and the hangar door leads to the Vehicle Range.'] },
  { id: 346, title: '2.23.81 · Gunsmith case fix', items: ['The gun in the gunsmith case lies along the case and sways a little instead of spinning, so long rifles and staffs no longer poke through the glass.'] },
  { id: 344, title: '2.23.79 · Slot buttons, gunsmith case, bridge map', items: ['Slots: the bet buttons (50, 250, 1000) and a big SPIN button are on the machine now, with a credit display. Click or tap them, or pull the lever with E. No more menu.', 'The gun mod bench is a gunsmith case: a steel cabinet with drawers, a glass case where your gun turns on a lit turntable, a tool pegboard and a GUNSMITH plaque. The Ship upgrades prompt no longer pops up when you stand at it.', 'The galaxy map on the bridge stands on a two-step lit dais with a holo table, and its railing goes all the way round. You can no longer walk through it.', 'The Interior styles camera stays inside the ship now, looking down the flight deck and the hallway with the ceiling in view.'] },
  { id: 342, title: '2.23.77 · Deck 6 fixes, a feud and an arrest', items: ['Slots: sit down at a machine with E, then click, press E or Space, or tap PULL. The crank drops and the reels spin. 1, 2 and 3 set the bet. WASD stands you up.', 'No guns on the arcade and casino deck. Your weapon is put away and firing is off.', 'The blackjack and high-low felts are the right way round now, and high-low has its own felt.', 'Poker players no longer stand inside chairs. The air hockey and skee-ball regulars stand beside their games, and the Star Racer kid sits in his seat.', 'Arcade plushies (Klunky, Blork, Frog E, Tiny Maw and a new Giant Blork) are prizes you can place in your ship from Decorate. Plushies you already won unlock too.', 'New quest: Gus Bitwhistle, the arcade manager, wants Lucky Lux poisoned. Outlaws spike his coffee, Marshals arrest Gus, and anyone else can do either or turn Gus in to Marshal Rook.', 'Marshals can arrest Vixen Glippo for soliciting S-grade drugs.', 'Anyone arrested or poisoned is gone for 3 in-game days, then comes back.'] },
  { id: 341, title: '2.23.76 · The Big Push', items: ['New story mission from General Hale at Fort Ironrock: Hold the Line. Pick up the field phone in the HQ dugout at the Front to begin.', 'Hold all six waves and the whistle blows: every trooper climbs the ladders and charges with you, and our fighters strafe the Drome trench.', 'The motor pool tank behind our line is yours for the push. Drive it around the end of our trench.', 'Clear their trench and a Drome Siege Walker drops in at their drop zone. Bring it down with the guns, the tank and everything you have.', 'First win: 8,000 cr, 25,000 XP, the Ironrock Trench Coat in the Wardrobe and the Ironrock Veteran paint on your Battle Tank. After that the field phone runs it as a repeatable event paying credits, XP and 6 Raid Tokens. Marshals also earn Marshal XP.'] },
  { id: 340, title: '2.23.75 · War in the sky over the Front', items: ['Fort Ironrock has no air, so the space battle overhead is in plain view: two of our cruisers and two Drome cruisers drift high above, trading laser broadsides with flashing hull hits and lit windows.', 'Fighter swarms chase each other in loops with tracers, flak bursts pop between them, and now and then a fighter spirals down trailing smoke and crashes.', 'In Hold the Line, a Drome cruiser breaks in two and falls during wave 5.', 'From wave 5 a siren warns of strafing runs: a Drome gunship dives along our trench and the dust walks down the line. Troopers on the fire step get cut down, and so do you unless you duck down onto the duckboards.', 'The Drome battery shells our line during waves (you hear the whistle first), and lobs the odd shell into no-man\'s-land the rest of the time. Every hit leaves a scorch mark.'] },
  { id: 339, title: '2.23.74 · Hold the Line', items: ['Pick up the field phone in the HQ dugout at the Front to start Hold the Line: six Drome waves against our trench, with a short lull between each to restock.', 'Wave 1 walks out in a line. Wave 2 crawls crater to crater under smoke. Wave 3 drops jump troops from a dropship. Wave 4 brings two Drome tanks. Wave 5 is a huge infantry push, and wave 6 is everything at once, led by two of Krag\'s lieutenants.', 'Grenades go both ways: our troopers lob them into no-man\'s-land and the Drome throw them into the trench.', 'Man the two MG nests on the parapet (V or WASD to leave). The field phone calls a three-gun barrage: aim where you want it and fire to mark the spot. It is the answer to the tanks.', 'Grenade and ammo crates, and an aid post that patches you up. If you die mid-battle you get back up at the aid post.', 'Each fallen trooper is replaced from a reserve of 40 shown on the battle HUD. If the reserve runs out and the step empties, or the Drome get into the trench in numbers, the line breaks. Hold all six and you earn 4,000 cr and 15,000 XP.'] },
  { id: 338, title: '2.23.73 · The Front: trenches at Fort Ironrock', items: ['The Siege Lines west of the fort are now The Front: two real trench lines about 75 m apart with no-man\'s-land between them.', 'Our trench is 2 m deep and zig-zags in fire bays, with timber walls, duckboards, a fire step, ladders to go over the top, a sandbag parapet with firing gaps, two MG nests, an aid post and an HQ dugout, and a communication trench that ramps up toward the fort gate.', 'No-man\'s-land has shell craters, barbed-wire belts on X-frames (with gaps), tank traps, shattered trees and burning Drome wrecks. Behind our line: an artillery battery, an ammo dump and a tank at the motor pool.', 'The Drome trench faces it in steel and red, with a gun battery and a lit drop zone behind it.', '20 of our troopers man the fire step: they pop up to fire bursts over the parapet, then duck to reload. If one falls, a replacement runs up the communication trench to take his place.', 'Drome riflemen hold their trench and every minute or so a group climbs out and advances. Trench walls block you (and your tank), ladders let you climb out, and the low gravity still lets you jump.'] },
  { id: 337, title: '2.23.72 · The Battle Tank drives like a tank', items: ['You sit in the turret of a real tank now: the hull, tracks and gun are under you instead of a floating barrel.', 'It is heavy: about 25 km/h flat out, slow to get moving and slow to stop. A and D turn the hull slowly, and it can pivot in place.', 'The turret swings after your aim on its own. A ring shows where the gun really points and turns green when it is on target.', 'Firing rocks the hull back, kicks out a dust ring and shakes the view. The tracks leave marks behind you and the engine rumbles.', 'It runs over small enemies, and the tank model has skirts, track links, exhausts, a mantlet, a muzzle brake, a cupola MG, smoke launchers and headlights.'] },
  { id: 336, title: '2.23.71 · A real cabin for the Velocity cars', items: ['The car interior has real surfaces now: quilted leather with orange stitching, suede, carbon-fibre weave and brushed aluminium.', 'A holographic HUD floats over the dash with your speed and drift or boost state.', 'LED shift lights across the top of the wheel climb from green to red with speed.', 'A centre console with a lit rotary drive knob, guarded toggles and a pulsing start button, an overhead switch panel, lit A-pillars, speaker grilles and quilted seat bolsters.'] },
  { id: 335, title: '2.23.70 · Every Zeltac deck looks different', items: ['Each working deck has its own floor, walls, ceiling and height now: brick and cobbles in the Market, green hull and wet panels in Hydroponics, rough stone in the Alien Quarter, wood panelling and a cream ceiling in the Senate Archive, steel on the Bridge.', 'Lower ceilings on the Market, Archive, Hydroponics and Alien decks so they feel like rooms, not hangars.', 'The deck number and deck name signs are lit lightboxes on the wall instead of flat planks.'] },
  { id: 334, title: '2.23.69 · The Neon Arcade and the Lucky Asteroid, rebuilt', items: ['Deck 6 is two real rooms under a low ceiling now: the Neon Arcade (cosmic carpet, neon ceiling grid) and, through a lit archway, the Lucky Asteroid casino (patterned carpet, wood panelling, coffered ceiling, chandeliers).', 'Twenty slot machines with real 3D reels that spin and land on the symbols you rolled. The old slots were built outside the wall, which is why they never worked.', 'New casino tables: roulette with Croupier Sol and a spinning wheel, and blackjack with Dealer Marlo. Poker, high-low and the cashier cage are rebuilt.', 'Five new arcade games: Blork Invaders, Star Racer (sit-down cabinets), air hockey, pinball and Neon Step.', 'Every sign is a real lit marquee, lightbox or plaque now. No more floating planks.', 'Marshals can arrest Arthur Vance in New Jamestown for buying stimulants. It pays Marshal XP and a seizure bounty, and he sits in a cell for 20 minutes.'] },
  { id: 333, title: '2.23.68 · The Roxy, rebuilt', items: ['The Roxy cinema in New Jamestown is a real art-deco picture palace now: stepped cream-and-maroon facade, a tall ROXY blade sign and a three-sided marquee with chasing bulbs, a ticket booth, poster lightboxes, brass doors, a terrazzo star and velvet ropes', 'Battle cars and tanks no longer creep backwards when you let off the gas, and a resting thumbstick no longer counts as brake'] },
  { id: 332, title: '2.23.67 · The Maw, reworked', items: ['Your guns hit the Greater Maw from the start again (they had stopped landing, so only your allies could hurt it), and hit harder until the squadron arrives', 'A new second stage, the Brood: it shuts its eye and grows armored sacs. Burst them all to force the eye open and stun it. The spawning stage and the enraged stage follow, then its last form', 'When a wingman dies, their ship blows apart in a fireball with burning wreckage, and the camera swings over in slow motion before snapping back to you', 'Every ally flies their own custom ship, and they keep their noses on the Maw'] },
  { id: 331, title: '2.23.66 · Thruster trails, Lulu\'s hair', items: ['Every thruster on your ship now leaves its own light trail, starting right at the nozzle. Change engines in the shipyard and the trails change with them', 'Lulu Sprinkles has a real hairstyle: a hairline, a side-swept fringe and a high ponytail that falls in a soft S, with a pink scrunchie'] },
  { id: 330, title: '2.23.65 · New trees on Earth', items: ['Earth\'s trees are replaced with proper low-poly trees: two leafy kinds with real branching trunks, plus a few bare dead trees for the war-torn look'] },
  { id: 329, title: '2.23.64 · Into the volcano', items: ['Capitone\'s Volcano Base has a Drome blast door in the cone now. Inside is the Volcano Forge: a tunnel, a huge cavern and a lava pit', 'Commander Vask fights from an island in the middle of the pit. His magma lifters rip lava out of the pit and throw it at you. A red circle marks where each one lands and fills up as it comes down, so keep moving', 'Grass sways in the wind on every grassy world', 'Lulu Sprinkles has a high blonde ponytail with a pink scrunchie', 'Trees no longer grow into the volcano base walls'] },
  { id: 328, title: '2.23.63 · Real sounds, arcade prizes, engine trails', items: ['Recorded room sound: McKlunkies, the mall food court, the Undercroft party and its muffled back room, Grub\'s Bar chatter, the New Jamestown park and the Neon Arcade', 'New recorded sounds for the pee break, the bar laughing at the end of the Mile Down, and the Greater Maw charging its big blast (now a long charge, a beat of silence, then a deep gut-blast)', 'Neon Arcade: Skee-Ball, claw machines, hoop shot and Whack-a-Blork, all paying tickets. Trade tickets at the prize counter for plushies and new ship furniture', 'Ships leave glowing light trails that fade out behind you', 'New engine sound: a heavy atomic jet, and the Miner chugs like a space diesel'] },
  { id: 327, title: '2.23.62 · One drummer', items: ['Grub\'s Bar: the old drummer from before the band was rebuilt was still standing behind the new kit. He\'s gone, so the Glonk Quartet has one drummer again'] },
  { id: 326, title: '2.23.61 · Doc\'s lab, ship cutaway, draw distance', items: ['Doc\'s lab: the chalkboard fits, tiled lab walls with pipes, valves and caged lamps, every jar holds a brain, and Doc lies sprawled on the floor instead of a white box', 'Interior styles: the camera rises to a cutaway of the whole flight deck and hallway with the ceilings lifted off, and the panel moves to the side', 'Far-away things no longer flicker or vanish (sharper depth everywhere)', 'Grub\'s Bar: drips fall from wet spots on the ceiling into puddles'] },
  { id: 325, title: '2.23.60 · Fixes', items: ['Heal button count is readable again', 'Hex Plates ship floor tiles line up with no seams', 'Watching a Cinema scene puts you back where you were', 'The Zeltac hologram map fits over its table again', 'The badge shine only sweeps across the metal star'] },
  { id: 324, title: '2.23.59 · Answer any time', items: ['Options show while a character is talking; picking one cuts the line off'] },
  { id: 323, title: '2.23.58 · Steady talk camera', items: ['The camera stays on whoever you are talking to for the whole conversation, through lists and follow-up boxes, and eases back out at the end', 'The talk view only opens for characters, not the Codex, terminals or signs'] },
  { id: 322, title: '2.23.57 · Voiced lines play in full', items: ['A recorded line now shows its words when the voice starts, and the options wait until it finishes (click the words or press Space to skip ahead)', 'The next lines of a conversation load while the current one plays', 'Highlighted buttons are steel blue instead of orange'] },
  { id: 321, title: '2.23.56 · New talk view', items: ['Talking to someone now frames them up close, with the conversation in a column beside them (bottom half on tall phones)', 'Every character with a line has a mouth that moves when they talk, following the real voice when there is a recording', 'Helmets get a comm light that pulses with the voice, robots get a glowing speaker grille', 'Keys 1 to 9 pick the options. Shops and big menus still open the full panel'] },
  { id: 320, title: '2.23.55 · Voice cast credits', items: ['Voice actors are named in the end credits and the Codex credits, with a link to email them or visit their site'] },
  { id: 319, title: '2.23.54 · Edit voice lines', items: ['Line text can be edited in Cast Voices; the game shows the new words and recordings stay matched'] },
  { id: 318, title: '2.23.53 · Radio presets', items: ['Six radio sounds for recorded voices (helmet, clean comms, closed visor, old radio, long range, robot speaker) with a strength setting per character'] },
  { id: 311, title: 'Forge bench and swing styles', items: ['On PC and phones held sideways the saber now lies big across a glowing work bench, with each part\'s arrows right under it. Tall phones keep the standing view', 'All new handles: smooth machined metal, plus three new grips (Fluted, Open Cage with a core that glows your blade colour, and Carved Wood) and a Ribbon Cap end with two trailing ribbons', 'Sparks drift around the saber and parts flash when you change them. The arrows no longer move while the saber floats', '12 swing styles to pick in the forge: Figure Eight, Side Sweep, Overhead Chop, Windmill, Rising Slash, Cross Cut, Sideways Eight, Lightning, Spiral, Lunge, Clover and Twirl', 'The light trail now runs the full length of the blade, and fades when the blade points at you so it never blinds you'] },
  { id: 310, title: 'Forge, your way', items: ['The saber forge is now one floating sword pulled apart into its parts, like the sketch', 'Tap the arrows beside a part to scroll its options. Parts you have not unlocked show grayed out with their price and a Forge button, or where to find the crystal', 'Tap the colour dot by a part to change its colour. Pick Double-ended at the bottom and the lower emitter and blade get their own arrows', 'Swing speed and the other upgrades sit behind the Upgrades button'] },
  { id: 309, title: 'The saber forge', items: ['Build your laser sword from parts: blade, crystal, emitter, grip and pommel, each with several new designs and its own colour', 'Parts have small trade-offs in damage, swing speed, reach and blocking; forge a part once, then swap for free', 'Double-ended: swap the pommel for a second emitter and blade with their own picks and colours; swings hit all around you', 'Twelve crystals, one hidden on each world under a beam of light, each with its own shape, colour and perk', 'Swing Speed upgrade now goes to 5 tiers, and the swing animation speeds up to match', 'Laser swords leave a light trail when you swing', 'Juno is now a saber smith, and the Kyber Laser Sword is now the Prism Laser Sword'] },
  { id: 308, title: 'Dome watch minimap', items: ['The minimap is now a high-dome watch: a metal case in your menu colours with a crown, cream lume bars and N E S W, an oil-dark rim and a curved glass highlight', 'The middle of the map bulges a little, like looking through an oil-filled dome', 'The classic map is redrawn: softer ground, shaded roads and water, raised buildings, enemy beads (bosses pulse), shop diamonds and gold quest marks', 'Works with the live camera map, your character token and space flight, and the compass is unchanged'] },
  { id: 307, title: 'Badge button fix', items: ['On phones the Marshal BADGE button now sits in the right-hand button column instead of on the minimap'] },
  { id: 306, title: 'Cockpit lasers on target', items: ['In cockpit view your lasers now fly straight up the aiming ring instead of landing below it'] },
  { id: 305, title: 'Mile Down lounge', items: ['The robot singer performs Deep Boop in the bar', 'The regulars sip, chat, look around and shoot pool instead of standing frozen', 'Talk to the regulars after the story for their take on the screaming'] },
  { id: 304, title: 'Mile Down touch-ups', items: ['The bar wall gap is sealed', 'The window looks out on a huge sunset sky with drifting clouds', 'Moody bar and lab lighting', 'Big E sits up, turns and steps down in one smooth motion', 'Pail carries Frog E in his hands', 'Big E no longer clips through the bar', 'Bar regulars and a robot lounge singer', 'Ask Mags about Big E, and get the lab key from her', 'Frog E gets the last word'] },
  { id: 303, title: '2.23.38 · Mile Down glow-up, your character on the minimap', items: ['The Mile Down bar was rebuilt so nothing clips through: rocks tucked into the corners, stalactites flush with the ceiling, wood wainscot round the walls', 'New in the bar: a mirrored back bar with lit bottle shelves, beer taps, a register and menu board, padded bar front, hanging lamps and string lights, round tables and chairs, an atomic rug, a pool table, a little stage with a mic, a real jukebox, photos, a mounted space-fish and cacti', 'Minimap: the round button under it (or the backslash key) swaps the arrow for your own character, in both the classic map and the live view'] },
  { id: 302, title: '2.23.37 · Live minimap', items: ['Click the minimap (or press = and -) to switch between the classic map and a live overhead camera at close, mid and far zoom', 'Indoors the camera looks down from just under the ceiling, so you see the room', 'Enemies, quest marks and your arrow are drawn on top. The game remembers your choice'] },
  { id: 301, title: '2.23.36 · The Mile Down', items: ['New side story in Earth Sky: Pail is waiting by a rusty elevator on the edge of the Floating City. His buddy Big E went down to see what is in the middle of the island', 'Ride a mile down the cliff to the Mile Down, a neon cave bar with a window onto the clouds', 'Behind the lab door, Doc has a retro horror experiment going. Movie-style cutscenes all the way through', 'Big E, the frog and the body all end up at the bar for good. Replay the ending from the Codex cinema'] },
  { id: 300, title: '2.23.35 · Greater Maw rebalance, straight ship guns and tidy posters', items: ['Greater Maw: the first phase has about a sixth less health, the final phase takes three times as much', 'The final phase fires four fans of lasers at once, spread in all directions, with one fan aimed at you', 'Ship bolts fly straight where you aim, even while strafing', 'Every ship weapon you own fires together when you hit fire', 'The cockpit sits lower so the reticle is in the middle of the view', 'Undercroft wanted posters no longer clip into the walls', 'New radio shows no longer pop the radio open: you get a note and press O to listen'] },
  { id: 299, title: '2.23.34 · Radio tile', items: ['The Radio tile in the tablet Journal shows the Nebula 88.8 player, like the other tiles show their models'] },
  { id: 298, title: '2.23.33 · Marshals and the band', items: ['Marshals can no longer hire a crew at Grub\'s bar. Taking the badge breaks up any crew you had, so no more wages or product', 'The Glonk band has a real keyboard player behind the keys, and the bass player now plays a sax'] },
  { id: 297, title: '2.23.32 · Lirra Vey, moon helmets and a new badge', items: ['The band in Grub\'s bar is rebuilt like the Undercroft one: a drummer behind a full kit, guitar, bass and keys, with shades and hats', 'New singer Lirra Vey: a green alien in a black sequined mermaid gown with big green eyes, red lips, antennae and opera gloves, under a warm pin spot', 'The Underworld is much darker now, with smoke hanging over the room', 'Anyone outside Luna Dome on the Moon wears a glass bubble helmet and an air pack', 'Marshal busts and manhunts no longer put a giant light beam on the suspect', 'A new Marshal badge: polished gold seven point star, GALACTIC MARSHALS seal, rank stars and a red rank ribbon', 'The radio now-playing bar no longer pops up; the radio itself still has the controls'] },
  { id: 296, title: '2.23.31 · Title crest, round 2', items: ['Only the top half of the sun shows, sitting just above SETTING SUN', 'The rifle is side on with its muzzle to the left, crossed with the sword in front of the sun', 'The crest is bigger and much more faded'] },
  { id: 295, title: '2.23.30 · Title crest', items: ['The glow behind the title screen is gone', 'New crest behind ART OF WAR: a striped setting sun with the Lvl 15 Rifle and Master Sword crossed over it, built from the game models'] },
  { id: 294, title: '2.23.29 · Blork logo, round 4', items: ['The Setting Sun now strafes at full speed and fires on the fly instead of stopping', 'Its shots come out of the wing guns like in game, in your laser color', 'BLORK STUDIOS is set in Gasoek One', 'The glow behind the title screen is menu blue instead of orange'] },
  { id: 293, title: '2.23.28 · Blork logo fixes', items: ['The ship in the Blork Studios intro now flies nose first', 'Smoother intro: blood is cached and the clock pauses through load stalls instead of skipping', 'Intro renders at the game default pixel size'] },
  { id: 292, title: '2.23.27 · Blork logo, take 2', items: ['The Blork Studios film now uses the game itself: a Drome trooper sprints down an Earth trail toward you, the Setting Sun drops in behind him and guns him down, his blood hits the lens and covers the screen, then drains away leaving BLORK written in dripping blood over STUDIOS'] },
  { id: 291, title: '2.23.26 · New Blork Studios logo', items: ['The Blork Studios card is now a one-shot film in the game\'s own style: a drone trooper runs across a dusk ridge, the Blork ship swoops in and shoots him, blood sprays over the screen, it floods red and BLORK STUDIOS is hand-lettered on top. Click to skip'] },
  { id: 290, title: '2.23.25 · Wake up on Earth', items: ['New characters now start by waking up at home: apartment 1C in the Jamestown Arms on Earth, first floor, third door on the left', 'B.U.R.P., the robot you built, sits on your desk, watches you and says good morning. Step out into the hallway and he tries something new', 'The elevator is broken down. The neighbours have opinions. The street door takes you out to Earth town and Captain Vega'] },
  { id: 289, title: '2.23.24 · Radio favorites, gates home', items: ['The radio keys work with the mouse again (the game was grabbing the mouse back on every click)', 'The radio is bigger. ▲ ▼ now cycle three lists: Nebula 88.8, All songs and Favorites', 'New heart key (or H): heart a song to add it to Favorites, press again to take it off. A heart on the screen shows it', 'The Forest of Life and the Swift Arena each have a warp gate back to Earth town'] },
  { id: 288, title: '2.23.23 · Radio in hand', items: ['Press O and the radio comes up in your hand on its own: no panel. Its keys do everything: ◀ ▶ pick, the middle key plays or pauses, ▲ ▼ switch between Shows and Songs.', 'Songs: every track you hear out in the galaxy is saved to the radio\'s Songs list, and it plays through them in order.', 'New pixel-art mouse cursor: gold arrow, cyan over anything you can click.'] },
  { id: 287, title: '2.23.22 · Pocket radio', items: ['The Nebula 88.8 radio is now a real little player: a chamfered body, a green screen with the show, time and progress, a d-pad and earbuds. Click its keys, or use the arrow keys and Enter.', 'It pops up asking if you want to listen when you first get it and whenever a new show comes on air.', 'B.U.R.P. stays quiet while a show is playing.'] },
  { id: 286, title: '2.23.21 · Nebula 88.8', items: ['New: the Nebula 88.8 pocket radio. Captain Vega gives it to you after Welcome to Earth. Press O, or Menu → Journal → Radio, to tune in.', 'Four shows come on air as the story moves on, each opening with the station ID. The music stops while a show plays, and it remembers where you stopped.', 'The Greater Maw battle now has everyone the history says came through: Vega, Skye, Ada-9, Hale, Elismas and Rell, plus your side (Marshals or outlaws).'] },
  { id: 285, title: '2.23.20 · The Maw barrage', items: ['In the Greater Maw\'s last form, its eye now charges a purple beam barrage: thin lines flicker in to show where they\'ll land, then a fan of thick beams burns for a few seconds. Fly out of the lines or take heavy damage.'] },
  { id: 284, title: '2.23.19 · Podcast', items: ['New: Podcast episodes. Each one unlocks after a quest, then plays from the pod (press O, or Menu → Journal → Podcast).', 'Episodes play over the music with it turned down low, pause for cutscenes, and remember where you stopped.', 'Owner editor: a new Podcast tab picks the quest and intro for each episode, live for everyone.'] },
  { id: 283, title: '2.23.18 · Lasers on target', items: ['Fixed the Bulldog Miner mining beam: it carves and breaks asteroids again, and the beam no longer stays stuck on screen.', 'Setting Sun lasers now fire straight to the reticle in both chase and cockpit view.', 'Cockpit view shows a single aiming ring at the centre of the screen.'] },
  { id: 282, title: '2.23.17 · Cockpit and menu fit', items: ['The menu tablet frame is now drawn right on the menu, so it lines up exactly whether you are on foot or flying.', 'The ship cockpit sits higher so the dash screens clear the HUD, the dash lip is gone and the side dials sit on panels.', 'The C Cockpit view hint now shows at the top of the screen.'] },
  { id: 281, title: '2.23.16 · Cutscene music', items: ['Location intro cutscenes now play that place\'s music, and boss intros play the boss music'] },
  { id: 280, title: '2.23.15 · Cockpit pass', items: ['Ship cockpit is shaded and deeper: lit panels, a dash lip, side consoles and a footwell','The bobblehead has its own clear plinth with a glow ring','Every gauge and meter reads something real: speed, hull, throttle, cruise, heading, missiles, EMP and radar contacts; the warning lamp only blinks on low hull','Aim at a raider in range and the ring turns red with a LOCK readout','Pick your bobblehead in the garage (new Bobblehead tab)','On PC a C · Cockpit view hint shows when you start flying or racing'] },
  { id: 279, title: '2.23.14 · Tablet, welder bot, the Don', items: ['Menu tablet now fits the whole menu on PC and while flying, and the scanline filter is replaced by a soft glass screen look','Surfaces no longer bend toward the screen edges (dropped the old PS1 texture warp)','Brakka\'s bay has a hover welder bot that works its way round the ship, clear of everything','McKlunkies: the Home of the Klunk wallpaper no longer flickers into the wall, and Don Klunkleone has a lit cigar'] },
  { id: 278, title: '2.23.13 · Twin blade guns, helmet fit', items: ['Twin blade wings: the gun is now one thin slab swept along both blade tips, joining them, with a slim barrel off the top and bottom blade','AR Screen helmet no longer clips with the head underneath'] },
  { id: 277, title: '2.23.12 · X-wing and AR Screen', items: ['Quad X-wing ship upgrade rebuilt: the regular wings now split into a proper X (two per side, same style), each with its own laser pod','New AR Screen helmet: gunmetal shell, wraparound green AR visor with HUD marks, sensor pod and antenna'] },
  { id: 276, title: '2.23.11 · Kayak fix', items: ['Paddling the kayak no longer uses the walking head-bob'] },
  { id: 275, title: '2.23.10 · Swimming fix', items: ['Underwater you only drift up while looking up. Looking level or down holds your depth, so you can dive properly'] },
  { id: 274, title: '2.23.9 · Bridge string lights', items: ['Earth Sky rope bridges are strung with warm 2400K bulbs that glow and twinkle at night'] },
  { id: 273, title: '2.23.8 · B.U.R.P. hatch fix', items: ['B.U.R.P.\'s hatch is now built flush into the starboard bridge wall','Talk to him and pick Power down to tuck him back inside; talk to the shut hatch to power him up again'] },
  { id: 272, title: '2.23.7 · Hanging bridges', items: ['Earth Sky islands are now linked by sagging rope bridges with plank decks and rope rails, no more ground clipping under them','B.U.R.P. now lives in a wall hatch on the bridge and swings out on a hinged arm to hang out with you'] },
  { id: 271, title: '2.23.6 · Sky fixes and the badge compass', items: ['Earth Sky bridges sit above the ground instead of fighting with it, and the airstrip has flat ground under it', 'Marshals: crimes nearby show a gold badge star on the compass with the distance'] },
  { id: 270, title: '2.23.5 · More sky', items: ['Earth Sky has three times the clouds: thick banks below, drifting wisps between the islands, and a high layer overhead'] },
  { id: 269, title: '2.23.4 · Earth Sky atmosphere', items: ['Cloud banks drift past and below the islands, with a high-altitude haze', 'Torches line the bridges and island edges, and flicker to life at night', 'The cloud sea and lighting are toned down so Earth Sky is no longer blinding', 'Nights up here go properly dark'] },
  { id: 268, title: '2.23.3 · Sky bridges and busts', items: ['Earth Sky bridges no longer clip into the islands', 'Marshals: a crime nearby now takes over the compass with the distance, and its red beacon shows through walls'] },
  { id: 267, title: '2.23.2 · Mobile stick', items: ['The move stick now appears wherever you put your left thumb, so you can strafe left at full speed'] },
  { id: 266, title: '2.23.1 · Quest tracking', items: ['You can track any quest in the journal, even ones you have not picked up yet. The tracker and compass point you to the quest giver', 'Quests the main story needs first (like Heavy Metal at Fort Ironrock) are now marked as main story'] },
  { id: 265, title: '2.23.0 · Kade stays home', items: ['Kade no longer follows you to other worlds after his fight'] },
  { id: 264, title: '2.22.99 · Marshals', items: ['Marshals can no longer raid merchant haulers in space'] },
  { id: 263, title: '2.22.98 · Main story in the journal', items: ['Main story quests are listed first in the journal, marked ★ MAIN, with where to find the quest giver', 'Dead Air (Chapter 5) starts right after Kade, so the main story never goes missing'] },
  { id: 262, title: '2.22.97 · Fixes from playtest', items: ['The Long Arm starts as soon as Robot City is freed and points you straight to Marshal Rook on the Zeltac', 'Kade\'s ship is no longer swallowed by fog in the cutscene', 'Arena Prime intro stays over the arena instead of showing the edge of the world', 'The betting bar only shows when you are at the Betting Pit', 'The crowd cheers during fights in the big ring', 'Galaxy map labels no longer cover each other, and Earth Sky sits beside Earth', 'The Marshal armory list no longer sticks around in other menus'] },
  { id: 261, title: '2.22.96 · Quest tracker', items: ['Quests you have not picked up yet now say which world the quest giver is on (like Ada-9 in Robot City)'] },
  { id: 260, title: '2.22.95 · Intro and Undercroft fixes', items: ['World intro flyovers no longer show striped floors', 'The Zeltac intro now flies through the plaza instead of showing the ship as a box in space', 'The Undercroft tip jar sits on the stage instead of floating in front of Vixen'] },
  { id: 259, title: '2.22.94 · Robot City', items: ['The old Hover Track is gone from Robot City, along with talk of the Hover Cup'] },
  { id: 258, title: '2.22.93 · Kayak respawn', items: ['Dying in a kayak now puts you back on foot when you respawn'] },
  { id: 257, title: '2.22.92 · Evidence and the badge button', items: ['Evidence locker: turn in drugs you find for half their street value plus Marshal XP', 'The BADGE button only shows once you are a Marshal (it was showing over the map on mobile)'] },
  { id: 256, title: '2.22.91 · Marshal Office', items: ['New ship room for Marshals: Marshal Office (500 CR)', 'One Marshal terminal: missions, bounty board, rank, armory (the extra bridge terminal is gone)', 'Evidence locker pays a stipend every 20 min', 'Holding cell with your arrest count', '+15% Marshal XP while you own the office'] },
  { id: 255, title: '2.22.90 · Shared world fallback', items: ['If a picked server can not be reached, the game drops back to the shared world everyone joins with Play.'] },
  { id: 254, title: '2.22.89 · Join through a tunnel', items: ['You can type or paste a tunnel address (like name.trycloudflare.com) into Multiplayer to join a server through it.'] },
  { id: 253, title: '2.22.88 · Character delete', items: ['Characters list has a delete button (asks first).', 'New character keeps the callsign you typed.'] },
  { id: 252, title: '2.22.87 · Join your own server by code', items: ['Joining by code now works on the PC that is hosting the server.'] },
  { id: 251, title: '2.22.86 · One-click Join', items: ['The button next to the code box is now Join and takes you straight in; it asks for a password if the server has one. Click a server in the list to see its rules first.'] },
  { id: 250, title: '2.22.85 · Server list refresh', items: ['The server list has a Refresh button and updates itself every 15 seconds while open.'] },
  { id: 249, title: '2.22.84 · Host from the game', items: ['Multiplayer has a Host a server box: download link, one-click launcher steps, and Find my server, which shows your join code and addresses with Copy buttons, Join my server and the control panel.'] },
  { id: 248, title: '2.22.83 · Title screen loading', items: ['The loading bar now shows over the Blork card and the title, and Press any key appears once the game is ready.'] },
  { id: 247, title: '2.22.82 · Faster intro, easy hosting', items: ['The Blork card shows the moment the game opens, no more long black screen.', 'Host Server launcher with a control panel: join code, your addresses with Copy buttons, rules, password, kick and ban.', 'Hosts can lock player settings like drugs and story scenes; your own choices come back when you leave.'] },
  { id: 246, title: '2.22.81 · Multiplayer help', items: ['Added a How to join or host guide to the Multiplayer screen.'] },
  { id: 245, title: '2.22.80 · Server list', items: ['Multiplayer now shows public servers with search, and you can join with a 6-letter code.'] },
  { id: 244, title: '2.22.79 · Server preview fix', items: ['Server preview now works when the game is opened from a secure link.'] },
  { id: 243, title: '2.22.78 · Intro fix', items: ['Fixed an error box that could pop up over the title screen.'] },
  { id: 242, title: '2.22.77 · Blork Studios', items: ['The studio is now Blork Studios, with a new intro card.'] },
  { id: 241, title: '2.22.76 · Multiplayer servers (early)', items: ['New Multiplayer button: preview a Blork server by address, see its rules and players, and join.', 'Your character comes with you to any server.'] },
  { id: 240, title: '2.22.75 · Blork intro', items: ['New Blork Studios card and Art of War title screen when the game opens.', 'Terms of Service, Privacy, License and Credits on the start screen, with a one-time agree box.', 'Offensive callsigns are blocked.'] },
  { id: 239, title: '2.22.74 · Co-op kill fix', items: ['Finishing off a monster another player was fighting now counts for both of you, so it no longer pops back to life.'] },
  { id: 238, title: '2.22.73 · Steadier ship screens', items: ['Terminal screens on the ship no longer flicker when you look at them from a distance or an angle.'] },
  { id: 237, title: '2.22.72 · Playtest fixes', items: ['Fixed a broken wall in the Zeltac mob hideout that could glitch the level.', 'Cleaned up material warnings in Bubble City, the Underworld, Marisol and the ship.', 'Full sweep of every world, the marshal path and the Kade fight.'] },
  { id: 236, title: '2.22.71 · The Galactic Marshals (part 2)', items: ['A Marshal board on your bridge, next to the bounty terminal. Your badge spins in, the stars fill, and a PROMOTED stamp lands when you rank up.', 'Marshal missions: hostage rescue, Drome Cutter sweeps, raider barge sweeps and manhunts for named fugitives on other worlds.', 'Random busts: crimes in progress show up near you with a red beacon. Flash your badge to arrest them, or chase them down if they run.', 'The Marshal armory (Lawgiver Pistol, Marshal Armor, Star Marshal Coat, Peacekeeper Rifle) and, at Senior Marshal, the Lawbringer Interceptor with a spinning light bar.', 'The Maw finale: Vega and her squadron fight beside your side, Marshals or outlaws, led by Rook or Kade.'] },
  { id: 235, title: '2.22.70 · The Galactic Marshals (part 1)', items: ['New story quest after Chapter 4: The Long Arm. Marshal Rook explains the choice between crime and the law, before Kade shows up.', 'After Kade teaches you to cook, Rook calls your ship and asks for his location. Turn him in and you can take the badge. Already past it? Ask Rook, or tap your record chip.', 'Marshals get a rank instead of an outlaw rating, and can flash their badge (N, or the BADGE button) for clout.', 'Marshals have no Lab, substances, fences, black market, hits or Don, and can\'t kill civilians. Turning in your badge is your call, from your Marshal card.'] },
  { id: 234, title: '2.22.69 · New wings and a cleaner cockpit', items: ['Three new Setting Sun wings: the Halo ring (a short cylinder around the hull, split at the top), Gull wings and Twin blades.', 'Cockpit: the blank grey boxes are gone, and the canopy struts are thinner, with lit strips, rivets, cables and clamp bands.', 'A pine tree air freshener now swings from the canopy.', 'The Bulldog Miner has four times the hull, and its auto aim locks onto asteroids from much wider.'] },
  { id: 233, title: '2.22.68 · Boss intros, world intros and the Tower of Death', items: ['Every big boss gets a short intro cutscene the first time you see it, with its name and a line or two.', 'Landing on a world for the first time plays a short flyover with what the place is about. Replay them from the Codex.', 'The Tower of Death lights up at night: red and amber windows, four sweeping searchlights on the roof and a pulsing red beacon.', 'Story scenes: Skip in Settings skips all of these.'] },
  { id: 232, title: '2.22.67 · Story fixes', items: ['The bounty hunter is now Kade, so he no longer shares a name with Admiral Sable in Chapter 5.', 'Tower of Death no longer ends with "Chapter 5 is being written". Ada warns you about the price on your head instead.'] },
  { id: 231, title: '2.22.66 · Kade, the bounty hunter', items: ['Kade, a crystal-headed bounty hunter, comes for you between Chapter 4 and Chapter 5. Ada has the lead: Price on Your Head.', 'A cutscene in the Arena Prime ring, then a boss fight. He blinks around the ring and throws a device that fills the floor with lasers. Jetpack up to dodge them.', 'Beat him and he invites you aboard the Glass Wake, a stolen Drome ship he repainted, and teaches you to cook.', 'The Lab can only be built after Kade shows you how. Anyone who already owns one keeps it.'] },
  { id: 230, title: '2.22.65 · Lasers, noses and a calmer cockpit', items: ['Setting Sun: four new noses in the garage: Hammerhead, Needle lance, Armored ram and Split jaw', 'Setting Sun lasers now fire glowing bolts that travel and hit what they reach, not instant lines. New Bolt speed upgrade: Standard, Fast, Hyper', 'Miner: the mining lasers are now a held, steady beam out of both arms, with the beam guns textures, sparks and hum', 'Pick a laser color for either ship in the garage: Ice blue, Solar, Venom, Crimson, Galaxy or White dwarf', 'Miner: new Beam upgrade (Overdrive, Cutter) for faster mining', 'Auto aim for ship lasers stays on by default and can be turned off in Settings', 'The cockpit lost its little random screens; cleaner panels in their place'] },
  { id: 229, title: '2.22.64 · The new Setting Sun and the hauler Miner', items: ['The Viper Fighter is merged into the Setting Sun: one fighter, rebuilt with a wedge nose, white canopy, tail fins and orange wingtip laser pods. If you bought the Viper, your 25,000 cr are refunded', 'The Setting Sun keeps the side thrusters, strafing and climbing, plus all the garage attachments: wings, engines, nose, guns and body kits', 'The Bulldog Miner is rebuilt as a boxy orange hauler with a white cab, roof radar and stacks, side ore trays full of crystals, and four glowing thrusters', 'The Miner fires blue mining lasers from its arms: great on asteroids, softer on ships', 'New paint: Hauler Orange'] },
  { id: 228, title: '2.22.63 · What you missed', items: ['Returning players get a one-time "What you missed this week" popup with the biggest new things, and a button to open the full update log'] },
  { id: 227, title: '2.22.62 · Ship polish and fixes', items: ['Other pilots now see your real ship: Fighter or Miner, with your paint job and parts (they used to see the starter)', 'Fixed: ship turrets were pointing their barrels away from you while shooting', 'Fixed: turret fire rate no longer depends on your frame rate', 'Fighter: drop is now X only, so Ctrl+W can no longer close the browser tab', 'More detail on all three ships: wingtip nav lights, panel seams, vents, canopy frames, antennas; the Miner gets rivets, a side hatch, ladder rungs and a cable spool'] },
  { id: 226, title: '2.22.61 · Boarding, rebuilt', items: ['Ship turrets can be shot down now. Each one drops credits and XP', 'Boarded ships are fully rebuilt inside: grated decks, ribbed and riveted walls, pipes and cable trays, hazard-striped door frames with lit room signs', 'Eight kinds of rooms: cargo, quarters, mess, armory, comms, med bay, engine room with a pulsing reactor, and a brig', 'A proper captain\'s bridge at the bow and a round airlock hatch at the stern', 'Enemies no longer spot you through walls, and your drone no longer shoots or fires missiles through them', 'The Shipyard is labeled on the bridge console and at Brakka'] },
  { id: 225, title: '2.22.60 · Raid ships, contracts and the mining cockpit', items: ['Raidable ships got a big upgrade: bridge towers, lit windows, armor panels, faction markings, three-bell engines and blinking running lights', 'Pirate and Drome ships now have gun turrets that track you and shoot when you get close', 'More ships to raid, spread over the bigger map', 'Rell on the Zeltac has new repeatable jobs: Raid Contracts if you are an outlaw, Hostage Rescues if you are not. The target ship gets a big marker', 'Hostage Rescue: clear the guards and cut three captives loose', 'The Bulldog Miner has its own cockpit: hazard trim, window grilles, a drill and ore hopper screen, and a spinning amber beacon'] },
  { id: 224, title: '2.22.59 · Fighter and Miner', items: ['Two new ships at the Shipyard (bridge console or Brakka): the Viper Fighter (25k) and the Bulldog Miner (20k). Switch any time', 'Garage for each ship: 9 paint styles (stripes, flames, camo, hazard, checker, tiger, carbon...), paint, accent, exhaust, and swappable wings, engines, noses, guns, body kits, drills, armor, cargo and lights', 'Fighter: side thrusters fire as you strafe, climb (Space) and drop (Ctrl/X), and stop on a dime', 'Miner: huge hull, takes 45% less damage, breaks rocks 2.5x faster and gets more ore', 'New Thrusters upgrade in Ship Systems: from floaty to on a dime', 'Space is twice as big, and raider packs are now spread all over it'] },
  { id: 223, title: '2.22.58 · Busier cockpit', items: ['More cockpit gadgets: two banks of flip switches with status lights, little scope screens on both sides, extra dials with moving needles, blinking button grids and a red digital clock'] },
  { id: 222, title: '2.22.57 · A proper cockpit', items: ['The ship cockpit gets riveted trim, corner plates, live gauges, glowing meters, toggle switches and a blinking warning lamp', 'Phones: the Menu tab is now a metal console tab with rivets and a glowing label'] },
  { id: 138, title: "2.19.7 · Roxy entrance and arcade fixes", items: ["The Roxy's doors and posters sit on the building front, with the marquee canopy and red carpet reaching out over the sidewalk", "The grey apartments behind the arcade turned to face the alley and moved back so they no longer press against the arcade", "Arcade cabinet side art no longer flickers as you walk past"] },
  { id: 137, title: "2.19.6 · Hand-painted town and plant textures", items: ["New pixel textures: brick for shops and the garage, stucco for homes and Town Hall, shingle roofs, and bark on tree trunks", "Building textures now tile at real size instead of one tile stretched across a whole wall", "New leaf and grass textures for every tree, bush and field in the game, with pixel clumps, highlights and tufts instead of blurry blobs"] },
  { id: 136, title: "2.19.5 · Signs and town fixes", items: ["Every sign in the game is now a pixel-art plaque with a bevelled frame, rivets, a pixel font and a drop shadow, and it is painted to the shape of its board so text is never squashed or stretched", "Fixed mirrored copies of two-sided signs (like the notice board and the arcade marquees) floating in the fields outside town", "The Roxy now faces West Avenue, so the park pond is behind it instead of at the door", "Houses no longer poke through the city wall: the apartments moved inward, two small houses were trimmed and three that could not fit were removed", "Town Hall columns stand out from the facade instead of inside it", "Street trees moved off the curb onto the sidewalk"] },
  { id: 135, title: "2.19.4 · New Jamestown, tidied up", items: ["Streets are clear: the scattered stalls, crates and bins are gone from the roads, and no bushes grow through the pavement", "One market row of four stalls on East Avenue, and a bench, bin and hydrant at each corner where the streets leave the plaza", "Parked hover cars sit at the curb instead of on the sidewalk", "Slick Eddie and Viper work the two back alleys west of Main Street, with crates and a dim lamp in each", "Arthur Vance's signing booth moved off West Avenue onto the sidewalk, the notice board moved off Main Street, and Bobby's BBQ no longer clips into the house behind it", "The Aranus Man comic reader matches the game's look, and its pages load much faster", "The Fort Ironrock iron wall texture now gets the same smoothing as every other texture in the HD styles"] },
  { id: 134, title: '2.19.3 · Fort Ironrock Armored Perimeter Walls', items: [
    'Fort Ironrock perimeter wall armor: The circular perimeter wall enclosing Fort Ironrock is now reinforced with riveted heavy iron plates, corner bolts, rust seams, and gunmetal coping caps.',
    'Retro graphics alignment: All new surfaces and structures pass through the authentic PS1 shader pipeline (discrete toon ramp, 320×240 vertex grid snapping, and affine texture warping).',
    'Custom texture asset: Embedded 64×64 pixel art riveted steel plate texture (TEX.ironwall) with nearest-neighbor filtering and repeat wrapping.'
  ] },
  { id: 133, title: '2.19.2 · New Jamestown Town Life · Stimulants, Arcades & Gazette', items: [
    'Stimulant dealing with Arthur Vance: Sell Focus Fizz, Stim Patches, Void Spice, and more to Arthur at his signing booth to fuel his writing on Issue #2. Focus Fizz pays a 2× premium (120 cr)!',
    'Playable retro arcade cabinets: Two full-sized coin-op cabinets (Space Snake & Space Rocks) stand outside the Neon Arcade on West Street, ready to play for high scores.',
    'Arcade Champion Pixel Pete: Hang out with Pete by the machines to talk high-score strategies and retro gaming.',
    'Feed Barnaby fresh fish: Treat Barnaby the cat to any fresh catch from Gil\'s Fish Market for a full heal, +50 XP, and a 10-minute Feline Agility (+15% move speed) buff.',
    'Cookie\'s Diner specials: Order savory Space Meatloaf (+10% dmg), piping hot Black Coffee (+15% speed), or Warm Cherry Pie at Cookie\'s Diner, complete with outdoor checkered cafe tables.',
    'Municipal Notice Board: Read local town bulletins, cinema showtimes, lost-and-found notices, and your active Outlaw Rep & Wanted status at the Central Plaza board.',
    'Cinema soundscape: Added dedicated auditorium acoustic profile with lowpass room wash, projector hum, and theater reverb.'
  ] },
  { id: 132, title: '2.19.1 · The Roxy Cinema & Dual-Channel Movies', items: [
    'The Roxy Cinema: walk into New Jamestown\'s grand movie palace on the west entertainment strip, featuring an art-deco neon marquee, double movie posters, ticket window, and double doors.',
    'Cinema auditorium: indoor screening room with sloped stadium seating tiers, plush red velvet armchairs, aisle step lights, proscenium velvet curtains, and concession stand with hot butter popcorn.',
    'Giant silver screen: 14.4m x 8.1m screen with black velvet framing borders, ambient screen glow illuminating the auditorium, and a volumetric projector beam shining from the projection booth.',
    'Dual-channel movie catalog: enjoy Night of the Living Dead (1968, CH 1) and Santa Claus Conquers the Martians (1964, CH 2) with independent timestamp progress.',
    'Channel switching: press C or use the TV/theatre prompts to change channels anytime in the cinema or on the ship\'s fishing room couch.',
    'Inactivity auto-hide: while seated and watching the film, on-screen prompts and buttons smoothly fade away after 2.8 seconds of inactivity, immediately restoring upon any mouse or keyboard input.'
  ] },
  { id: 131, title: '2.19 · New Jamestown Revamp & The Astonishing Aranus Man', items: ['New Jamestown full city overhaul: distinct civic, commercial, entertainment, residential, and park districts with brick facades and slate mansard roofs.', 'Arthur Vance book signing booth: meet the author of The Astonishing Aranus Man, read the 10-page in-game comic book, help his writer\'s block, and fix the Arena match for an exclusive Aranus Cape and signed comic.', 'Shady street runners: recruit Slick Eddie and Viper in the alleys to move product across the city using your Outlaw reputation.', 'Bobby the Grillmaster: sizzling backyard BBQ kettle grill behind the diner with hot space patties.', 'Barnaby the Cat: friendly neighborhood orange tabby in the park you can pet for purrs and warm fuzzies.', 'First-person inhaler animation: taking substances now shows a custom inhaler with clear glass chamber dynamically glowing in the drug\'s color.'] },
  { id: 130, title: "2.18.12 · Bridge layout", items: ["The galaxy map and the captain's chair sit a little further back on the bridge"] },
  { id: 129, title: "2.18.11 · Cleaner terminals", items: ["Room terminals are plain bridge consoles again, with no screen above", "Removed the floating screen beside the drone bay"] },
  { id: 128, title: "2.18.10 · Room terminals and the drone bay", items: ["Every ship room terminal now matches the new bridge consoles, with a screen above", "The drone bay moved behind the two upgrade consoles and got a new cradle with a hovering drone"] },
  { id: 127, title: '2.18.9 · Captain\'s chair and the Marshal terminal', items: ['A proper captain\'s chair on a swivel base with armrest controls', 'The Bounty terminal is a real console with a Marshal star screen'] },
  { id: 126, title: '2.18.8 · Bridge, finished', items: ['A ceiling dome with a glowing ring over the map, cable runs and light panels', 'The galaxy map sits on a railed platform with a planet hologram', 'Framed wall panels with status lights replace the blue strips'] },
  { id: 125, title: '2.18.7 · A nicer bridge', items: ['The ship bridge has neat new consoles with screens and buttons, glowing floor trim, wall light bars and ceiling ribs'] },
  { id: 124, title: '2.18.6 · A tougher Maw', items: ['The Greater Maw has twice the health, last phase included', 'Its teeth point the right way'] },
  { id: 123, title: '2.18.5 · Kids swing their arms right', items: ['Kids in the Residential Ring swing their arms from the shoulders'] },
  { id: 122, title: '2.18.4 · Easy furniture removal, chat closes', items: ['While decorating your ship, look at a piece and press E to remove it (or click it in Remove mode)', 'Chat closes again with Enter or Escape'] },
  { id: 121, title: '2.18.3 · Leaderboards on your own server', items: ['Leaderboards, the Marshal board and the Hit board now work when the game is played from server.js (like through your tunnel), not only on the claude.ai page'] },
  { id: 120, title: '2.18.2 · New den wallpaper', items: ['New fish wallpaper in the Angler\'s Den, drawn by Phil'] },
  { id: 119, title: '2.18.1 · Worm Hole line', items: ['At the Worm Hole the fishing line now comes from the tip of your rod'] },
  { id: 118, title: '2.18 · Codex items', items: ['New Items tab in the Codex: every item in the game, with who drops it, who sells it and which quest gives it', 'Items fill in as you find them; locked ones show ??? but still tell you where to look', 'Search by item, enemy or world, and filter by category with found counts'] },
  { id: 117, title: '2.17.2 · Den comforts', items: ['The TV switch only shows up when you stand right at the TV, so you can watch from the couch', 'Ship music pauses while the den TV is on and comes back when you turn it off or leave', 'Tan wallpaper with little fish in the Angler\'s Den', 'The Worm Hole camera tilts up so you can see the whole TV while you fish'] },
  { id: 116, title: '2.17.1 · New type and the movie', items: ['New fonts: Tektur for titles and headings, WDXL Lubrifont TC for reading text and chat', 'Night of the Living Dead now plays on the Angler\'s Den TV', 'The high-low table\'s cards and chips sit on the felt, and the stools are on the players\' side'] },
  { id: 115, title: '2.17 · Movie night in the Angler\'s Den', items: ['The Angler\'s Den has a TV playing Night of the Living Dead (1968). It remembers where you stopped, pauses when you leave the room and turns the ship music off while it plays', 'A couch you can sit on. Move to get up', 'Angler\'s Den Lv 5 adds the rainbow Worm Hole: an ice-fishing hole that can bite with any fish in the game. You can fish it from the couch while the movie plays', 'Ice holes use a short jigging rod held low over the hole', 'The rod rack stands the rods up instead of leaving them on the floor, and the speaker no longer covers a trophy plaque', 'The Jellopod\'s tentacles trail behind it now', 'Every helmet is built once per trooper, fixing helmets that crashed in game but previewed fine'] },
  { id: 114, title: '2.16 · Side hustles, a clearer ocean and Vega on the radio', items: ['Sell drugs to the President (he pays way too much) and to random people. Some refuse, and in lawful places someone might report you', 'Give your partner product to sell from their apartment or your ship quarters, then collect the earnings. Push it too hard and they get arrested; post bail with Marshal Rook', 'Your bag shows one tile each for guns, staffs, melee and ordnance with a picture of the weapon. Tap it to pick from the whole list. Weapons and ordnance no longer take bag space or weight', 'Ocean World cleaned up: no torn water, no domes showing through the surface, floors sit on the seabed, no sky underwater, taller glass tunnels', 'Every world\'s water matches its colors', 'Vega is the only voice in the cutscenes and does all the battle radio at the Greater Maw, fully voiced', 'New space fonts and a light space blue in place of the orange', 'Fullscreen works in more browsers. On iPhone, Add to Home Screen to play fullscreen', 'The casino carpet no longer flickers and the high-low table looks like a table', 'Mezar shows its name on the galaxy map'] },
  { id: 113, title: '2.15 · The Lucky Asteroid, the Undercroft dive and a bigger lounge', items: ['The Neon Arcade has a casino now: the Lucky Asteroid. Six slot machines, a high-low table and a space poker table with Rook and Nyx. Win real credits', 'Two playable arcade cabinets: SPACE SNAKE and SPACE ROCKS. Good scores pay out a few credits', 'The Undercroft is a proper hive of scum and villainy: the Rusty Rivet bar, a band, back-room poker with One-Eye Jax, a members-only back room, wanted posters, drunks and smoke', 'The Starlight Lounge got a second bar, VIP couches, plants, waiter bots and people mingling. The President has his own spot and the dancers no longer walk through him', 'When a person and a thing are both in reach (like your partner and your bed), the one you are looking at gets the button. Your roommate also stands away from the bunk now', 'Romance music only plays while you are talking to them', 'Q, Y and the weapon box all cycle gun, staff, melee. Staffs are their own magic slot again', 'The weapon box stays the same size for ammo, spells and the shield', 'New energy shield: a glowing kite shield with the setting-sun sigil', 'Muzzle flashes now come out of the end of each barrel', 'Earth no longer shrinks and vanishes when you look at it from the Moon'] },
];
const UPDATES_LATEST = Math.max(...UPDATES.map(u => u.id));
function updateRows(list) {
  const rows = document.createElement('div'); rows.className = 'rows'; rows.id = 'shopRows'; rows.style.maxHeight = '46vh'; rows.style.overflowY = 'auto';
  // the newest few open; older ones fold down to their title, tap to read
  list.slice().sort((a, b) => b.id - a.id).forEach((u, i) => { const d = document.createElement('div'); d.className = 'row'; d.style.display = 'block'; const fold = i >= 4;
    const h = document.createElement('b'); h.textContent = (fold ? '▸ ' : '') + u.title; h.style.color = '#ffd36a'; d.appendChild(h);
    const ul = document.createElement('ul'); ul.style.margin = '4px 0 2px 18px'; ul.style.padding = '0'; u.items.forEach(t => { const li = document.createElement('li'); li.textContent = t; ul.appendChild(li); }); d.appendChild(ul); rows.appendChild(d);
    if (fold) { ul.hidden = true; d.style.cursor = 'pointer'; d.addEventListener('click', () => { ul.hidden = !ul.hidden; h.textContent = (ul.hidden ? '▸ ' : '▾ ') + u.title; SFX.ui(); if (typeof pageRows === 'function') pageRows(); }); } });
  $('dlgActs').before(rows);
}
function openUpdates(missedOnly) {
  const seen = S.seenUpd || 0, list = missedOnly ? UPDATES.filter(u => u.id > seen) : UPDATES;
  if (!list.length) return false;
  openDlg(missedOnly ? `${list.length} update${list.length > 1 ? 's' : ''} since you last played` : 'Update log', 'B.U.R.P.');
  $('dlgLine').textContent = missedOnly ? `While you were gone, ${S.nick || 'Trooper'}, the universe got bigger. Here's what you missed:` : 'Everything new, newest first.';
  updateRows(list); acts([['Got it', () => { S.seenUpd = UPDATES_LATEST; markDirty(); closeDlg(); }, true]]);
  S.seenUpd = UPDATES_LATEST; markDirty(); return true;
}
